local config = {
  ui_story_5068_50680101_1_dialog_content = "<color=#e8d9bb><size=50>Crash!!!</size></color>",
  ui_story_5068_50680101_2_dialog_content = "(... Why...)",
  ui_story_5068_50680101_3_dialog_content = "Ouch!",
  ui_story_5068_50680101_4_dialog_content = "Why does this lunatic bite everyone she sees?! Good thing I reacted quickly!",
  ui_story_5068_50680101_5_dialog_content = "How dare you sneak up on us?! We ain't nobody's easy target! Kill them, now!",
  ui_story_5068_50680101_6_dialog_content = "Let's just see which of us ends up dead.",
  ui_story_5068_50680101_7_dialog_content = "(... How did things end up like this?)",
  ui_story_5068_50680101_8_dialog_content = "Ugh!",
  ui_story_5068_50680101_9_dialog_content = "What the heck?! This is insane! Everyone, draw your weapons! Quick!!!",
  ui_story_5068_50680101_10_dialog_content = "<color=#e8d9bb>Bam! Bam!</color>",
  ui_story_5068_50680101_11_dialog_content = "Ahhh!",
  ui_story_5068_50680101_12_dialog_content = "Don't let any of 'em slip away!!!",
  ui_story_5068_50680101_13_dialog_content = "<color=#e8d9bb><size=45>Bam! Bam! Bam!</size></color>",
  ui_story_5068_50680101_14_dialog_content = "What... What exactly is going on here?!",
  ui_story_5068_50680101_15_dialog_content = "Lady Sheol!!!",
  ui_story_5068_50680101_16_dialog_content = "You said this job wasn't dangerous at all—!!",
  ui_story_5068_50680101_17_dialog_content = "<color=#e8d9bb>One day ago</color>",
  ui_story_5068_50680101_18_dialog_content = "Wow, this place is so grand now! That's the Cloudrover Guild for you—or maybe this is all thanks to you, Lady Sheol?",
  ui_story_5068_50680101_19_dialog_content = "I haven't been here in a while, but this place has expanded like crazy. I almost lost my way just now.",
  ui_story_5068_50680101_20_dialog_content = "Heheh, is it really that impressive? I'm sure it's nothing compared to your magnificent Colossus.",
  ui_story_5068_50680101_21_dialog_content = "I see you came alone today... Where are the young ladies who are usually at your side? Don't tell me they actually got lost in the Cloudrover Guild?",
  ui_story_5068_50680101_22_dialog_content = "Well, the job was classified as \"very low-risk,\" so even though I can't fight at all, I figured...",
  ui_story_5068_50680101_23_dialog_content = "A-Ahem! Besides, I don't want to keep bothering my friends with stuff like this! They need their rest too!",
  ui_story_5068_50680101_24_dialog_content = "I see. Your words give me no choice but to reassess my impression of you.",
  ui_story_5068_50680101_25_dialog_content = "Doing things on your own isn't necessarily a bad thing, but never forget that there will always be times when we need to rely on others.",
  ui_story_5068_50680101_26_dialog_content = "Thanks for the concern, but don't worry. I know my own limits better than anyone else, which is why I'm always careful when I operate on my own.",
  ui_story_5068_50680101_27_dialog_content = "I have no reason to worry if you're the one helping me. Still, I should make something perfectly clear: your pay will be determined by how many heads you bring me.",
  ui_story_5068_50680101_28_dialog_content = "What?!?",
  ui_story_5068_50680101_29_dialog_content = "Heheh, your reactions are always the most entertaining. But enough joking for now, let's move on to actual business.",
  ui_story_5068_50680101_30_dialog_content = "The truth is, this job can't be done without you, which is why I wouldn't dare to put you in danger.",
  ui_story_5068_50680101_31_dialog_content = "Come take a look at this.",
  ui_story_5068_50680101_32_dialog_content = "What is it?",
  ui_story_5068_50680101_33_dialog_content = "Just take your time and look it over carefully.",
  ui_story_5068_50680101_34_dialog_content = "I can vaguely see something in there. Is that... a ball of black mist?",
  ui_story_5068_50680101_35_dialog_content = "No... It's no ordinary mist. I can sense something inside... A unique presence.",
  ui_story_5068_50680101_36_option_content = "Force Boost!",
  ui_story_5068_50680101_37_dialog_content = "Wait, is this...?!",
  ui_story_5068_50680101_38_dialog_content = "There used to be Lumina inside this mist!",
  ui_story_5068_50680101_39_dialog_content = "Used to be?",
  ui_story_5068_50680101_40_dialog_content = "Yes! There used to be Lumina within this mist, but it's completely gone now... All except for a few traces, which I could only sense by using my powers.",
  ui_story_5068_50680101_41_dialog_content = "... Do you see anything else?",
  ui_story_5068_50680101_42_dialog_content = "No.",
  ui_story_5068_50680101_43_dialog_content = "Are you sure? I need you to be absolutely certain of this.",
  ui_story_5068_50680101_44_dialog_content = "Is this why you need my help? To look into this weird black mist?",
  ui_story_5068_50680101_45_dialog_content = "Indeed, but this is only one part of the job. The starting point, to be precise.",
  ui_story_5068_50680101_46_dialog_content = "I knew it wouldn't be that simple.",
  ui_story_5068_50680101_47_dialog_content = "In the last few days, a highly dangerous disease has been spreading throughout Umbraton... or so I think.",
  ui_story_5068_50680101_48_dialog_content = "Wow, I don't think I've ever heard you sound so unsure.",
  ui_story_5068_50680101_49_dialog_content = "Is that so? In any case... \"spread\" may not be the best word to describe it.",
  ui_story_5068_50680101_50_dialog_content = "This disease strikes in frequent, concentrated outbreaks, but it doesn't appear to follow any sort of pattern. The afflicted areas are scattered randomly across Umbraton, like raindrops falling from the sky. It makes tracking the disease frustratingly difficult.",
  ui_story_5068_50680101_51_dialog_content = "So it's not contagious?",
  ui_story_5068_50680101_52_dialog_content = "I can't be sure, but my initial findings indicate as much. However, this isn't the most troublesome aspect of the disease.",
  ui_story_5068_50680101_53_dialog_content = "What would that be?",
  ui_story_5068_50680101_54_dialog_content = "The symptoms.",
  ui_story_5068_50680101_55_dialog_content = "What about them?",
  ui_story_5068_50680101_56_dialog_content = "Everyone knows that different illnesses have different symptoms. For example, a person suffering from a cold would exhibit different symptoms than someone suffering from an upset stomach.",
  ui_story_5068_50680101_57_dialog_content = "Naturally, certain illnesses share similar symptoms as well, like a common cold and pneumonia. However, this isn't the case with Umbraton's mysterious disease.",
  ui_story_5068_50680101_58_dialog_content = "The people who have been recently affected by it are all exhibiting different symptoms...",
  ui_story_5068_50680101_59_dialog_content = "Some feel excruciating pain throughout their entire body, some have completely lost their voice, and some have collapsed from exhaustion due to uncontrollable mania... And these are only some of the many inexplicable symptoms that were recently reported.",
  ui_story_5068_50680101_60_dialog_content = "Then isn't it possible that they're suffering from different illnesses?",
  ui_story_5068_50680101_61_dialog_content = "I can't deny that possibility, but don't you find it strange?",
  ui_story_5068_50680101_62_dialog_content = "Based on our previous findings, these people were completely symptom-free just prior to falling ill. If it was just one or two people, we could call it a coincidence.",
  ui_story_5068_50680101_63_dialog_content = "But what if it applied to the vast majority of cases? Because more than ninety percent of patients were perfectly healthy one day and then seriously ill the next day.",
  ui_story_5068_50680101_64_dialog_content = "Could that really be just a coincidence?",
  ui_story_5068_50680101_65_dialog_content = "So you're saying...",
  ui_story_5068_50680101_66_dialog_content = "This.",
  ui_story_5068_50680101_67_dialog_content = "Sorry, Lady Sheol, but I don't really follow...",
  ui_story_5068_50680101_68_dialog_content = "This is the one thing every patient has in common.",
  ui_story_5068_50680101_69_dialog_content = "Regardless of symptoms or locations, there's one thing that ties these seemingly isolated cases together.",
  ui_story_5068_50680101_70_dialog_content = "You mean... this black mist?",
  ui_story_5068_50680101_71_dialog_content = "Exactly. The majority of people in every infected area reported seeing this black mist at some point.",
  ui_story_5068_50680101_72_dialog_content = "Needless to say, my subordinates put themselves in life-threatening danger to acquire this specimen.",
  ui_story_5068_50680101_73_dialog_content = "Life-threatening danger?!",
  ui_story_5068_50680101_74_dialog_content = "Be careful... I have no way of knowing what would happen if this mist were to leak out of its container.",
  ui_story_5068_50680101_75_dialog_content = "Please don't leave out important details like this next time you ask for help—",
  ui_story_5068_50680101_76_dialog_content = "Anyway... You don't expect me to analyze the composition of the black mist, do you?",
  ui_story_5068_50680101_77_dialog_content = "If that's the case, I'm sorry to disappoint you but my psychic abilities can only do so much.",
  ui_story_5068_50680101_78_dialog_content = "Rest assured, analyzing the black mist is not the reason why I've called you here today.",
  ui_story_5068_50680101_79_dialog_content = "I simply require your help with locating the origins of the mist.",
  ui_story_5068_50680101_80_dialog_content = "Do you suspect... that someone <color=#FFB400>purposely</color> released the black mist in Umbraton?",
  ui_story_5068_50680101_81_dialog_content = "I still can't say for certain, which is precisely why I need your help.",
  ui_story_5068_50680101_82_dialog_content = "This job doesn't sound very safe to me...",
  ui_story_5068_50680101_83_dialog_content = "I only need you to report any suspicious findings to me. There's no need to delve too deeply into things, much less interact with others.",
  ui_story_5068_50680101_84_dialog_content = "The legendary Caelestite should have no trouble with something this simple.",
  ui_story_5068_50680101_85_dialog_content = "If that's the case, I should be able to avoid most dangerous situations using my powers. But still...",
  ui_story_5068_50680101_86_dialog_content = "I'm well-prepared to compensate you generously for your troubles. Should the job take longer than expected, I'll also pay you accordingly.",
  ui_story_5068_50680101_87_dialog_content = "Ah, that's not what I mean... There's just one thing I still don't understand.",
  ui_story_5068_50680101_88_dialog_content = "The black mist doesn't seem to be affecting the Cloudrover Guild in any noticeable way, so why are you going so far out of your way to investigate it?",
  ui_story_5068_50680101_89_dialog_content = "Or maybe, unbeknownst to me, you've suddenly become passionate about charity?",
  ui_story_5068_50680101_90_dialog_content = "... Is that really how you see me? You still have a long way to go, young man.",
  ui_story_5068_50680101_91_dialog_content = "Doing business is more than just buying or selling. This isn't me being charitable; I'm simply paying the necessary costs to ensure continued business.",
  ui_story_5068_50680101_92_dialog_content = "So that's it...",
  ui_story_5068_50680101_93_dialog_content = "Alright, that covers everything. The rest is up to you now, PlayerName.",
  ui_story_5068_50680101_94_dialog_content = "<color=#e8d9bb>After you leave...</color>",
  ui_story_5068_50680101_95_dialog_content = "<color=#e8d9bb>Beep—Beep—</color>",
  ui_story_5068_50680101_96_dialog_content = "It's me.",
  ui_story_5068_50680101_97_dialog_content = "Lady Sheol! I'll be right there!",
  ui_story_5068_50680101_98_dialog_content = "Okay.",
  ui_story_5068_50680201_1_dialog_content = "I ended up in such a gloomy place while chasing after that black mist... I wonder if this place falls within Umbraton's jurisdiction. I really hope it does.",
  ui_story_5068_50680201_2_dialog_content = "<color=#e8d9bb>Huff... puff...</color>",
  ui_story_5068_50680201_3_dialog_content = "Eek—I just felt a chill down my spine. Does anyone actually live in these houses? It feels like something's gonna suddenly jump out at me...",
  ui_story_5068_50680201_4_option_content = "I should just go back.",
  ui_story_5068_50680201_5_dialog_content = "No, no, I've already gotten this far. I should...",
  ui_story_5068_50680201_6_option_content = "I should keep going!",
  ui_story_5068_50680201_7_dialog_content = "I only have to find where the black mist came from and report it to Lady Sheol. I don't have to worry about what happens after that.",
  ui_story_5068_50680201_8_dialog_content = "Besides, I can't just give up halfway through! I've got to toughen up!",
  ui_story_5068_50680201_9_option_content = "Force Boost",
  ui_story_5068_50680201_10_dialog_content = "Hmm... It looks like I'm getting close to the origin of the black mist.",
  ui_story_5068_50680201_11_dialog_content = "I really didn't expect things to go this smoothly. I guess Lady Sheol wasn't lying about the job's danger level after all.",
  ui_story_5068_50680201_12_dialog_content = "Help! Is anyone there? Help!",
  ui_story_5068_50680201_13_dialog_content = "Huh? Am I hearing things, or did someone just call out for help?",
  ui_story_5068_50680201_14_dialog_content = "You, you, you! Stay away! Help! Somebody, HELP—!",
  ui_story_5068_50680201_15_dialog_content = "Roar—!",
  ui_story_5068_50680201_16_dialog_content = "Ahhhh—!",
  ui_story_5068_50680201_17_dialog_content = "Oh no! There's no time—",
  ui_story_5068_50680201_18_dialog_content = "Outta my way!!!",
  ui_story_5068_50680201_19_dialog_content = "Huh?",
  ui_story_5068_50680201_20_dialog_content = "How did Eclipsites manage to reach this place?!",
  ui_story_5068_50680202_1_dialog_content = "(Incredible! She wiped out every Eclipsite before I even had time to react!)",
  ui_story_5068_50680202_2_dialog_content = "There shouldn't be any more Eclipsites, at least for now. You okay?",
  ui_story_5068_50680202_3_dialog_content = "... I'm fine, no worries. That was a close call. Thanks for saving me, <color=#FFB400>Miss Assistant</color>.",
  ui_story_5068_50680202_4_dialog_content = "Don't mention it. I can't believe Eclipsites managed to worm their way in here even though it's still part of Umbraton. Talk about unlucky!",
  ui_story_5068_50680202_5_dialog_content = "How'd you end up running into them?",
  ui_story_5068_50680202_6_dialog_content = "I-I'm not quite sure. I had just finished work, and on my way back, the fog rolled in suddenly, and everything turned pitch black, and then...",
  ui_story_5068_50680202_7_dialog_content = "(... \"Fog\"? \"Everything turned pitch black\"? Could this be what I think it is?!)",
  ui_story_5068_50680202_8_dialog_content = "Then I suddenly felt sick and thought about going to the <color=#FFB400>doctor</color> to get it checked out, but...",
  ui_story_5068_50680202_9_dialog_content = "But then you ran into those things... Today really isn't your day, huh?",
  ui_story_5068_50680202_10_dialog_content = "It's just the way it is. Folks like us have no other option but to live in these remote slums.",
  ui_story_5068_50680202_11_dialog_content = "When something goes wrong here... no one cares at all. If I weren't lucky enough to get your help, I'd probably have...",
  ui_story_5068_50680202_12_dialog_content = "Hey, hey, quit with the waterworks! You're fine, aren't you? I made it out without a scratch too, so everything's okay!",
  ui_story_5068_50680202_13_dialog_content = "Can you still stand?",
  ui_story_5068_50680202_14_dialog_content = "Huh? It seems my legs are failing me...",
  ui_story_5068_50680202_15_dialog_content = "Sigh...",
  ui_story_5068_50680202_16_dialog_content = "I'm sorry, I'm really useless. It's not a big deal, but I...",
  ui_story_5068_50680202_17_dialog_content = "Nah, that's not what I meant. Everyone gets scared when they see Eclipsites, so don't be too hard on yourself.",
  ui_story_5068_50680202_18_dialog_content = "It's just... the <color=#FFB400>doctor</color> is gonna have one more patient today.",
  ui_story_5068_50680202_19_dialog_content = "Here, gimme your hand and I'll help you up!",
  ui_story_5068_50680202_20_dialog_content = "Thank you, Miss Assistant. I'm really sorry; you saved me, but I've caused you so much trouble... Actually, I could be on my own now...",
  ui_story_5068_50680202_21_dialog_content = "What, you think you can make it out of here on your own? Gimme a break!",
  ui_story_5068_50680202_22_dialog_content = "What if more Eclipsites show up? What would you do then?",
  ui_story_5068_50680202_23_dialog_content = "Besides, I just finished running some errands for the doctor and was on my way back to the clinic. If you have enough energy to talk a bunch of nonsense, then stand up and come with me.",
  ui_story_5068_50680202_24_dialog_content = "Thank you...",
  ui_story_5068_50680202_25_dialog_content = "... Save it for when the doctor treats you, now get moving!",
  ui_story_5068_50680202_26_dialog_content = "Wait... I'm not seeing things, am I? That lady...",
  ui_story_5068_50680202_27_dialog_content = "Her body seems to be covered in something that resembles the black mist!",
  ui_story_5068_50680202_28_dialog_content = "This is bad, I need to catch up to them!",
  ui_story_5068_50680301_1_dialog_content = "I knew it. The presence of the black mist is extremely intense over here!",
  ui_story_5068_50680301_2_dialog_content = "This house doesn't stand out in any way, making it a perfect hiding place... I really can't believe I finished my job so easily.",
  ui_story_5068_50680301_3_dialog_content = "Now all I have to do is report to Lady Sheol, and—",
  ui_story_5068_50680301_4_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5068_50680301_5_dialog_content = "...",
  ui_story_5068_50680301_6_dialog_content = "...",
  ui_story_5068_50680301_7_dialog_content = "Uh... H-Hello?",
  ui_story_5068_50680301_8_dialog_content = "Who are you? And why are you hanging around here?",
  ui_story_5068_50680301_9_dialog_content = "Ah, I...",
  ui_story_5068_50680301_10_dialog_content = "It's because... My stomach... It hurts...",
  ui_story_5068_50680301_11_dialog_content = "I heard this was a clinic...",
  ui_story_5068_50680301_12_dialog_content = "...",
  ui_story_5068_50680301_13_dialog_content = "My stomach... It really hurts...",
  ui_story_5068_50680301_14_dialog_content = "...",
  ui_story_5068_50680301_15_dialog_content = "(That cold gaze... It's like she's staring right into my soul. Don't tell me... Has she already seen right through me?!)",
  ui_story_5068_50680301_16_dialog_content = "... Ah... Well... It looks like I'm in the wrong place... C-Could you point me towards the clinic?",
  ui_story_5068_50680301_17_dialog_content = "I-I can go find it for myself...",
  ui_story_5068_50680301_18_dialog_content = "Sorry to bother...",
  ui_story_5068_50680301_19_dialog_content = "Hold it!",
  ui_story_5068_50680301_20_dialog_content = "(Oh no, the jig is up! I'd better make a run for it!)",
  ui_story_5068_50680301_21_dialog_content = "Didn't you hear me?! I said hold it!",
  ui_story_5068_50680301_22_dialog_content = "Huh? Is she going to attack me?!",
  ui_story_5068_50680302_1_dialog_content = "Growl—",
  ui_story_5068_50680302_2_dialog_content = "Phew... So there was an Eclipsite behind me all along? I was fine to begin with, but her attack just now was scary enough to make me feel sick...",
  ui_story_5068_50680302_3_dialog_content = "\"Fine\"? I thought you said your stomach hurt?",
  ui_story_5068_50680302_4_dialog_content = "—!!!",
  ui_story_5068_50680302_5_dialog_content = "Now that you mention it, it's starting to hurt again... The Eclipsite must've scared me so badly that I forgot about the pain.",
  ui_story_5068_50680302_6_dialog_content = "Urgh... My stomach... It's killing me...",
  ui_story_5068_50680302_7_dialog_content = "What a weird guy... Come on in, I guess.",
  ui_story_5068_50680302_8_dialog_content = "You're in the right place. This is the clinic.",
  ui_story_5068_50680302_9_dialog_content = "... You should be fine now. Go home and get plenty of rest, and don't push yourself at work for the next two days.",
  ui_story_5068_50680302_10_dialog_content = "Thank you, <color=#FFB400>Doctor</color>. I'm feeling much better now. But...",
  ui_story_5068_50680302_11_dialog_content = "What is it? Are you still feeling sick?",
  ui_story_5068_50680302_12_dialog_content = "No, no, no. Your medical skills are exceptional, and I'm feeling fine now. It's just... the medical bill...",
  ui_story_5068_50680302_13_dialog_content = "Don't worry if you can't cover my fee right now. Just put it on your tab and pay me later like usual.",
  ui_story_5068_50680302_14_dialog_content = "Everyone knows each other around here, so just come back when you have the money.",
  ui_story_5068_50680302_15_dialog_content = "Thanks a lot! I really appreciate it! I'm always on credit, and it's truly embarrassing...",
  ui_story_5068_50680302_16_dialog_content = "Don't stress so much about that. It's never a good idea to let a medical problem go untreated, so come see me whenever you need to, okay?",
  ui_story_5068_50680302_17_dialog_content = "Yup! Oh... Looks like there's a new patient. I won't take more of your time, Doctor.",
  ui_story_5068_50680302_18_dialog_content = "(The source of the black mist is... the doctor?)",
  ui_story_5068_50680302_19_dialog_content = "(It feels really similar, but... something feels really different too. What could it be?)",
  ui_story_5068_50680302_20_dialog_content = "Hello, what seems to be the problem?",
  ui_story_5068_50680302_21_dialog_content = "(If it's really her... what could she be after?)",
  ui_story_5068_50680302_22_dialog_content = "(Is she doing it on purpose? Could she be making people sick in order to have more patients?)",
  ui_story_5068_50680302_23_dialog_content = "(No, that can't be it. I just saw her waive that girl's medical bills for now, and it doesn't seem to be the first time either.)",
  ui_story_5068_50680302_24_dialog_content = "The doctor asked you a question, now quit gawking at her like that! Let me warn you, if you lay your eyes on something you're not supposed to, not even she can fix what happens to your eyes!",
  ui_story_5068_50680302_25_dialog_content = "That's enough, you're scaring our patient. Now then... What exactly is wrong with him?",
  ui_story_5068_50680302_26_dialog_content = "He was complaining about his stomach hurting earlier...",
  ui_story_5068_50680302_27_dialog_content = "Yes... That's right, it's my stomach.",
  ui_story_5068_50680302_28_dialog_content = "That reminds me, who told you about the clinic in the first place?",
  ui_story_5068_50680302_29_dialog_content = "Ah... J-Just some friendly stranger. He saw how much pain I was in, so he told me about a nearby clinic and how to find it.",
  ui_story_5068_50680302_30_dialog_content = "—!",
  ui_story_5068_50680302_31_dialog_content = "...",
  ui_story_5068_50680302_32_dialog_content = "(Uh, what's going on? Did I say something I shouldn't have said...?)",
  ui_story_5068_50680302_33_dialog_content = "Uhhhhh... Ugh, ahhhh!",
  ui_story_5068_50680302_34_dialog_content = "It hurts! AHHH! It's killing me!",
  ui_story_5068_50680302_35_dialog_content = "This is—",
  ui_story_5068_50680302_36_dialog_content = "He was recovering just a while ago, so how could this be? If I don't treat him immediately...",
  ui_story_5068_50680302_37_dialog_content = "I feel really sick... Doctor, am I going to die? Please, I don't want to die...",
  ui_story_5068_50680302_38_dialog_content = "Aaaaaahhh!!!",
  ui_story_5068_50680302_39_dialog_content = "Stop thinking about things like that! I'll treat you right away, so don't be scared. Everything's going to be okay...",
  ui_story_5068_50680302_40_dialog_content = "(That's—)",
  ui_story_5068_50680302_41_dialog_content = "Huh?",
  ui_story_5068_50680302_42_dialog_content = "Things just go in one ear and out the other with you, don't they? Didn't I tell you to keep your eyes to yourself?!",
  ui_story_5068_50680302_43_dialog_content = "I'm sorry! I didn't mean to look!",
  ui_story_5068_50680302_44_dialog_content = "(... If I'm not mistaken, this doctor is using Lumina to heal her patients. The mist only comes out while she's treating them.)",
  ui_story_5068_50680302_45_dialog_content = "(But it's different from the stuff that Lady Sheol gave me. Her mist is full of Lumina, while Lady Sheol's specimen doesn't have any at all.)",
  ui_story_5068_50680302_46_dialog_content = "(Does this mean I was wrong? No, it's still too early to say for sure! Maybe the Lumina is only present during her treatment, and then it gets depleted once it's over. After that...)",
  ui_story_5068_50680302_47_dialog_content = "(Without any Lumina left, it turns into that harmful black mist! It's possible that the doctor doesn't know how to handle it, so she disposes of it in secret.)",
  ui_story_5068_50680302_48_dialog_content = "(But these are just my own assumptions; whether or not they're right is for Lady Sheol to figure out. It could be that I'm completely wrong about all of this.)",
  ui_story_5068_50680302_49_dialog_content = "You're fine now. Try to get some rest, and you'll be cured by the time you wake up.",
  ui_story_5068_50680302_50_dialog_content = "Emm...",
  ui_story_5068_50680302_51_dialog_content = "Phew!",
  ui_story_5068_50680302_52_dialog_content = "(She looks relieved to see her patient in stable condition. I don't think she's faking it either.)",
  ui_story_5068_50680302_53_dialog_content = "You've already treated way too many patients today, Doctor. Get some rest for now, and I'll \"handle\" this last patient.",
  ui_story_5068_50680302_54_dialog_content = "It's fine, I can take care of him. But... you're probably right about having too many patients. We're done accepting new patients for today, so please shut the door.",
  ui_story_5068_50680302_55_dialog_content = "Sure.",
  ui_story_5068_50680302_56_dialog_content = "(?!)",
  ui_story_5068_50680302_57_dialog_content = "My assistant tells me that you're suffering from stomach pain, is that right?",
  ui_story_5068_50680302_58_dialog_content = "Is it a chronic illness?",
  ui_story_5068_50680302_59_dialog_content = "Well...",
  ui_story_5068_50680302_60_dialog_content = "Or maybe you ate something that wasn't particularly clean?",
  ui_story_5068_50680302_61_dialog_content = "Um...",
  ui_story_5068_50680302_62_dialog_content = "Hmm... You don't seem willing to tell me, but don't worry...",
  ui_story_5068_50680302_63_dialog_content = "I have plenty of highly effective medicines for combating stomach pain, regardless of the cause.",
  ui_story_5068_50680302_64_dialog_content = "See?",
  ui_story_5068_50680302_65_dialog_content = "With just a single injection, no amount of pain will ever bother you again. You won't even remember the pain you felt before.",
  ui_story_5068_50680302_66_dialog_content = "Wait a second!",
  ui_story_5068_50680302_67_dialog_content = "I... I suddenly feel much better!",
  ui_story_5068_50680302_68_dialog_content = "...",
  ui_story_5068_50680302_69_dialog_content = "S-Sorry for bothering you, Doctor! I'll definitely come back to see you if my pain returns!",
  ui_story_5068_50680302_70_dialog_content = "Bye—",
  ui_story_5068_50680302_71_dialog_content = "Now who said you could leave?",
  ui_story_5068_50680302_72_dialog_content = "(Looks like escape isn't an option anymore...)",
  ui_story_5068_50680302_73_dialog_content = "You... didn't come here looking for treatment, did you?",
  ui_story_5068_50680401_1_dialog_content = "You... didn't come here looking for treatment, did you?",
  ui_story_5068_50680401_2_dialog_content = "I-I did, I swear! It's just that I suddenly feel much better now!",
  ui_story_5068_50680401_3_dialog_content = "It's crazy, right? Maybe... Maybe it was just a passing thing?",
  ui_story_5068_50680401_4_dialog_content = "Do you take us for idiots or something? Drop the act already!",
  ui_story_5068_50680401_5_dialog_content = "You're the type who has to learn things the hard way, aren't you? I don't mind teaching you a lesson, but fair warning...",
  ui_story_5068_50680401_6_dialog_content = "This might <color=#FFB400>actually</color> hurt!",
  ui_story_5068_50680401_7_dialog_content = "Wh-What are you gonna do to me?!",
  ui_story_5068_50680401_8_dialog_content = "Alright... That's enough, you two.",
  ui_story_5068_50680401_9_dialog_content = "You don't seem to have any ill intent, considering you haven't tried attacking us after all this time... Am I right?",
  ui_story_5068_50680401_10_dialog_content = "... That's right!",
  ui_story_5068_50680401_11_dialog_content = "Not this again, Doctor.",
  ui_story_5068_50680401_12_dialog_content = "You're such a soft-hearted person. I don't think it's a bad thing, or else I wouldn't... Anyway, if you keep trusting others so easily, then sooner or later—",
  ui_story_5068_50680401_13_dialog_content = "I know you're worried about me, but I know what I'm doing. Trust me.",
  ui_story_5068_50680401_14_dialog_content = "Besides, this place belongs to us. As long as you're by my side, I have nothing to worry about.",
  ui_story_5068_50680401_15_dialog_content = "...",
  ui_story_5068_50680401_16_dialog_content = "Now then, could you please tell us why you were pretending to be ill?",
  ui_story_5068_50680401_17_dialog_content = "But my stomach really did hurt just now...",
  ui_story_5068_50680401_18_dialog_content = "Ugh, give it a rest already! You blew your own cover a long time ago, or haven't you realized it yet?!",
  ui_story_5068_50680401_19_dialog_content = "Is my acting really that bad...?",
  ui_story_5068_50680401_20_dialog_content = "It didn't take much to get you to admit it... You must be a pretty honest person.",
  ui_story_5068_50680401_21_dialog_content = "If your acting was any better, we'd be much more suspicious of you. To be honest, the most telling part of your act was a single statement.",
  ui_story_5068_50680401_22_dialog_content = "Ah... J-Just some friendly stranger. He saw how much pain I was in, so he told me about a nearby clinic and how to find it.",
  ui_story_5068_50680401_23_dialog_content = "My clinic isn't very big, and it's fairly well-hidden. On top of that, we have a very special rule here—",
  ui_story_5068_50680401_24_dialog_content = "Anyone who visits the clinic must be personally introduced by someone we know.",
  ui_story_5068_50680401_25_dialog_content = "All of my patients know that I don't accept patients with unknown backgrounds, which means they would never recommend me to anyone unfamiliar to them.",
  ui_story_5068_50680401_26_dialog_content = "As soon as you said that, we both knew you were lying to us.",
  ui_story_5068_50680401_27_dialog_content = "I see...",
  ui_story_5068_50680401_28_dialog_content = "My assistant and I need to keep a low profile for reasons we're unable to disclose.",
  ui_story_5068_50680401_29_dialog_content = "I've already told you much more than is necessary... So would you mind telling us why are you here?",
  ui_story_5068_50680401_30_dialog_content = "The truth is... I was tasked to investigate a strange disease running rampant through Umbraton lately. And my investigation brought me to this place.",
  ui_story_5068_50680401_31_dialog_content = "At first I thought I had an important lead, but in the end I think I got the wrong person...",
  ui_story_5068_50680401_32_dialog_content = "...",
  ui_story_5068_50680401_33_dialog_content = "...",
  ui_story_5068_50680401_34_dialog_content = "Still making up stories, eh?!",
  ui_story_5068_50680401_35_dialog_content = "N-No, I swear it's the truth!",
  ui_story_5068_50680401_36_dialog_content = "There's no need to keep wasting your time on this guy, Doctor. Besides, he saw your treatment method just now.",
  ui_story_5068_50680401_37_dialog_content = "Is... Is that so? In that case, all I can say is that I'm sorry.",
  ui_story_5068_50680401_38_dialog_content = "(Oh no, it looks like I'm in real trouble now... What are they gonna do with me?!)",
  ui_story_5068_50680401_39_option_content = "Force Boost!",
  ui_story_5068_50680401_40_dialog_content = "(I'm really sorry, but to keep <color=#FFB400>Eleanor</color> and myself safe, I have no other choice but to do this.)",
  ui_story_5068_50680401_41_dialog_content = "(You must have taken on this job fairly recently, right? If so, this shot will make you forget everything that happened in the last month...)",
  ui_story_5068_50680401_42_dialog_content = "(Once you're asleep, I'll have Eleanor drop you off somewhere safe. You shouldn't have set foot in this clinic.)",
  ui_story_5068_50680401_43_dialog_content = "(<color=#FFB400>Rebecca</color> is still way too kind of a person.)",
  ui_story_5068_50680401_44_dialog_content = "(I knew this guy was no good from the moment he walked in and started babbling nonsense. If it were up to me, I would've thrown him out with the rest of the trash without a second thought.)",
  ui_story_5068_50680401_45_dialog_content = "(This Rebecca lady doesn't seem to want to hurt me, and her assistant really listens to her.)",
  ui_story_5068_50680401_46_dialog_content = "(If I had never intruded on them, she probably wouldn't need to do this to me. But maybe... maybe I still have a chance to earn her trust?)",
  ui_story_5068_50680401_47_dialog_content = "(I only have one shot at this!)",
  ui_story_5068_50680401_48_dialog_content = "Wait! Have you been treating a lot of patients with mysterious symptoms lately?",
  ui_story_5068_50680401_49_dialog_content = "Quit trying to stall for time!",
  ui_story_5068_50680401_50_dialog_content = "... It's fine, let him speak.",
  ui_story_5068_50680401_51_dialog_content = "Er, well, I don't know why you two are being so secretive, but I can tell that you really do have the interests of your patients at heart, Doctor.",
  ui_story_5068_50680401_52_dialog_content = "Maybe we can work together to find the root of these strange illnesses?",
  ui_story_5068_50680401_53_dialog_content = "Hmm... You mentioned that your job involves investigating a strange disease, right? Have you made any other progress?",
  ui_story_5068_50680401_54_dialog_content = "Just this.",
  ui_story_5068_50680401_X54_dialog_content = "Have you seen anything like this before, Dr. Rebecca? As a doctor, you should know way more about this than I do.",
  ui_story_5068_50680401_55_dialog_content = "—!!!",
  ui_story_5068_50680401_56_dialog_content = "Wh-What are you doing with this?! Where did you find it?!",
  ui_story_5068_50680401_57_dialog_content = "Wait! How do you know Rebecca's name?!",
  ui_story_5068_50680401_58_dialog_content = "(Ah! I let it slip!)",
  ui_story_5068_50680401_59_dialog_content = "Spit it out before I force it out of you!",
  ui_story_5068_50680401_60_dialog_content = "Wait, unless... you're with the <color=#FFB400>Black Wolves</color>, aren't you?!",
  ui_story_5068_50680401_61_dialog_content = "The Black Wolves? Who are they?",
  ui_story_5068_50680401_62_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5068_50680401_63_dialog_content = "Did someone say this was a clinic? A dump like this?",
  ui_story_5068_50680401_64_dialog_content = "It's a bit run-down, but look at the stuff inside; this is indeed a clinic!",
  ui_story_5068_50680401_65_dialog_content = "Those masks... Are the Black Wolves really behind all of this?",
  ui_story_5068_50680401_66_dialog_content = "Don't try anything funny! Your buddies here already told us everything!",
  ui_story_5068_50680401_67_dialog_content = "Wait, stop! I don't know these people at all! We're not working together, I swear!",
  ui_story_5068_50680401_68_dialog_content = "Tsk. Doctor! Doctor, come out fast! Who's the doctor here?",
  ui_story_5068_50680401_69_dialog_content = "I heard the doctor here can treat illnesses caused by the black mist. Get your butt out here, now!",
  ui_story_5068_50680401_70_dialog_content = "There's no doctor here! But if you're looking for a reason to see one, I'll gladly give it to you!",
  ui_story_5068_50680401_71_dialog_content = "Get lost, you scum!",
  ui_story_5068_50680401_72_dialog_content = "Ouch!",
  ui_story_5068_50680401_73_dialog_content = "Why does this lunatic bite everyone she sees?! Good thing I reacted quickly!",
  ui_story_5068_50680401_74_dialog_content = "How dare you sneak up on us?! We ain't nobody's easy target! Kill them, now!",
  ui_story_5068_50680401_75_dialog_content = "Let's just see which of us ends up dead.",
  ui_story_5068_50680401_76_dialog_content = "Ugh!",
  ui_story_5068_50680401_77_dialog_content = "What the heck?! This is insane! Everyone, draw your weapons! Quick!!!",
  ui_story_5068_50680401_78_dialog_content = "<color=#e8d9bb>Bam! Bam!</color>",
  ui_story_5068_50680401_79_dialog_content = "Ahhh!",
  ui_story_5068_50680401_80_dialog_content = "Don't let any of 'em slip away!!!",
  ui_story_5068_50680401_81_dialog_content = "<size=45><color=#e8d9bb>Bam! Bam! Bam!</color></size>",
  ui_story_5068_50680401_82_dialog_content = "(What's happening here... How did things end up like this?!)",
  ui_story_5068_50680401_83_dialog_content = "(The door's completely blocked off. I couldn't escape even if I wanted...)",
  ui_story_5068_50680401_84_dialog_content = "<color=#e8d9bb>Beep—Beep—</color>",
  ui_story_5068_50680401_85_dialog_content = "Come on! Pick up, Lady Sheol!!",
  ui_story_5068_50680502_1_dialog_content = "A bunch of idiots! This guy's with you, isn't he? If you don't want anything to happen to him—",
  ui_story_5068_50680502_2_dialog_content = "I told you we're not working together...",
  ui_story_5068_50680502_3_dialog_content = "Is this woman out of her mind? She picked a random guy and claimed he was one of our Black Wolves. Do any of you know this dude?",
  ui_story_5068_50680502_4_dialog_content = "No. Do you know him?",
  ui_story_5068_50680502_5_dialog_content = "What a coincidence; I don't know him either.",
  ui_story_5068_50680502_6_dialog_content = "Hahahahaha!",
  ui_story_5068_50680502_7_dialog_content = "That's what I've been telling you all along! Why won't you believe me?!",
  ui_story_5068_50680502_8_dialog_content = "Holding me hostage won't do either of you any good, so could you please take the knife away from my neck? I could really get hurt...",
  ui_story_5068_50680502_9_dialog_content = "Shut up! Even if you're not in league with these guys, you're still trash in my eyes!",
  ui_story_5068_50680502_10_dialog_content = "Just let him go. We don't want any innocent bystanders to get hurt.",
  ui_story_5068_50680502_11_dialog_content = "Innocent is the last word I'd use to describe this guy.",
  ui_story_5068_50680502_12_dialog_content = "But if even the doctor is saying that... Then consider this your lucky day.",
  ui_story_5068_50680502_13_dialog_content = "Let me make this clear! Anyone messing with the Black Wolves won't end well!",
  ui_story_5068_50680502_14_dialog_content = "You know, we were actually thinking of peacefully taking over this whole neighborhood. But now, it looks like stomping it out is a better option!",
  ui_story_5068_50680502_15_dialog_content = "...",
  ui_story_5068_50680502_16_dialog_content = "So what exactly are you idiots doing here then?",
  ui_story_5068_50680502_17_dialog_content = "Wait a minute! I know you! You're—",
  ui_story_5068_50680502_18_dialog_content = "You're Eleanor!",
  ui_story_5068_50680502_19_dialog_content = "...",
  ui_story_5068_50680502_20_dialog_content = "That's right! I remember now! I know you!",
  ui_story_5068_50680502_21_dialog_content = "Huh? El... what? It doesn't ring any bells.",
  ui_story_5068_50680502_22_dialog_content = "Eleanor! I mean—",
  ui_story_5068_50680502_23_dialog_content = "Eh...",
  ui_story_5068_50680502_24_dialog_content = "I'm really sorry...",
  ui_story_5068_50680502_25_dialog_content = "But if this keeps up, you're only going to make more trouble for us... You left me no choice...",
  ui_story_5068_50680502_26_dialog_content = "Uhh...",
  ui_story_5068_50680502_27_dialog_content = "Just relax, I promise it won't hurt too much...",
  ui_story_5068_50680502_28_dialog_content = "What!? What did you do to him?!",
  ui_story_5068_50680502_29_dialog_content = "Don't worry, I have no intention of taking anyone's life.",
  ui_story_5068_50680502_30_dialog_content = "As you can see, I just rendered him unconscious.",
  ui_story_5068_50680502_31_dialog_content = "This, this woman, she's insane... Withdraw... Move, move!",
  ui_story_5068_50680502_32_dialog_content = "Go back and report to the bosses! Let the higher-ups—",
  ui_story_5068_50680502_33_dialog_content = "Ugh!!!",
  ui_story_5068_50680502_34_dialog_content = "Sorry, but I can't let any of you escape.",
  ui_story_5068_50680502_35_dialog_content = "If even one of you manages to leave with your memories intact... It'll make even more trouble for me.",
  ui_story_5068_50680502_36_dialog_content = "I'm sorry, Miss Rebecca. That guy must've recognized me from my wandering days...",
  ui_story_5068_50680502_37_dialog_content = "It's fine, Eleanor, I knew this day would come sooner or later. It was only a matter of time.",
  ui_story_5068_50680502_38_dialog_content = "(All it took was a single attack...)",
  ui_story_5068_50680502_39_dialog_content = "(It seems Rebecca wasn't fighting at her full strength against those Black Wolves.)",
  ui_story_5068_50680502_40_dialog_content = "(She looks so frail, but she's actually really powerful... I don't think she's just an ordinary doctor.)",
  ui_story_5068_50680502_41_dialog_content = "As for you, rest assured that I have no intention of doing the same to you... At least not right now.",
  ui_story_5068_50680502_42_dialog_content = "You don't need to worry about these people either.",
  ui_story_5068_50680502_43_dialog_content = "You remember the shot I was going to give you earlier? To tell the truth, it wasn't actually medicine.",
  ui_story_5068_50680502_44_dialog_content = "Miss Rebecca? Don't you think you're telling him too much?",
  ui_story_5068_50680502_45_dialog_content = "Don't worry. I know what I'm doing.",
  ui_story_5068_50680502_46_dialog_content = "The serum in the shot isn't medicine, but <color=#FFB400>poison</color>... The same kind that I just administered to these people.",
  ui_story_5068_50680502_47_dialog_content = "Poison?!",
  ui_story_5068_50680502_48_dialog_content = "Yes, poison... But it's not lethal.",
  ui_story_5068_50680502_49_dialog_content = "These people... are just unconscious, nothing more.",
  ui_story_5068_50680502_50_dialog_content = "When these villains wake up, they'll forget who they are and what they were up to!",
  ui_story_5068_50680502_51_dialog_content = "I'm sorry, little boy... Did we scare you just now?",
  ui_story_5068_50680502_52_dialog_content = "I'm not scared at all!",
  ui_story_5068_50680502_53_dialog_content = "Then are you feeling better?",
  ui_story_5068_50680502_54_dialog_content = "I'm feeling a lot better now! Thanks, Doctor!",
  ui_story_5068_50680502_55_dialog_content = "Good... You seem to be perfectly fine, which means you can go home now.",
  ui_story_5068_50680502_56_dialog_content = "The clinic isn't very safe right now, so do me a favor and tell everyone to stay away for the time being.",
  ui_story_5068_50680502_57_dialog_content = "And remember to keep everything that happened here a secret, got it?",
  ui_story_5068_50680502_58_dialog_content = "Understood! Consider it done!",
  ui_story_5068_50680502_59_dialog_content = "Then I'll head back for now! Goodbye, Doctor! Goodbye, Miss Assistant!",
  ui_story_5068_50680502_60_dialog_content = "Eleanor... Could you please dispose of these people now?",
  ui_story_5068_50680502_61_dialog_content = "—!",
  ui_story_5068_50680502_62_dialog_content = "Please don't misunderstand. I only mean for her to take them someplace safe and far away from here.",
  ui_story_5068_50680502_63_dialog_content = "Why are you telling him all of this, Miss Rebecca? Just knock him out so I can dispose of him with the others!",
  ui_story_5068_50680502_64_dialog_content = "I've changed my mind.",
  ui_story_5068_50680502_65_dialog_content = "... I don't understand.",
  ui_story_5068_50680502_66_dialog_content = "I failed to notice it earlier... Maybe it's because we've been hiding out in this tiny clinic for the last year?",
  ui_story_5068_50680502_67_dialog_content = "The slums and this clinic... They've given us protection, but they've also narrowed our perspective somewhat.",
  ui_story_5068_50680502_68_dialog_content = "I had no idea that there were still Caelestites in the world.",
  ui_story_5068_50680502_69_dialog_content = "...",
  ui_story_5068_50680502_70_dialog_content = "Caelestites? What are those?",
  ui_story_5068_50680502_71_dialog_content = "Didn't you notice? Like, something that didn't feel quite like usual when you were fighting?",
  ui_story_5068_50680502_72_dialog_content = "I guess it did feel a little different...",
  ui_story_5068_50680502_73_dialog_content = "It felt like... like I could see different patterns of Lumina all around me! It made fighting even smoother than usual!",
  ui_story_5068_50680502_74_dialog_content = "Then it wasn't just my imagination, it seems.",
  ui_story_5068_50680502_75_dialog_content = "And if my hunch is correct... Then that makes you a Caelestite, doesn't it?",
  ui_story_5068_50680502_76_dialog_content = "The only ones capable of using such a special technique to aid us in battle are the Caelestites of legend.",
  ui_story_5068_50680502_77_dialog_content = "You accidentally mentioned my name earlier, which you probably learned through those same abilities, right?",
  ui_story_5068_50680502_78_dialog_content = "You seem to know a lot about the Caelestites.",
  ui_story_5068_50680502_79_dialog_content = "Just from what I've read in books about the past. I was under the impression that the Caelestites were all...",
  ui_story_5068_50680502_80_dialog_content = "I'm sorry, I just... never expected to meet a Caelestite like this.",
  ui_story_5068_50680502_81_dialog_content = "Well, you're right. My name's PlayerName, and I really am a Caelestite. Who exactly are you two?",
  ui_story_5068_50680502_82_dialog_content = "Just a <color=#FFB400>nameless doctor</color> and her <color=#FFB400>nameless assistant</color>. That's all you need to know!",
  ui_story_5068_50680502_83_dialog_content = "Eleanor... PlayerName was kind enough to introduce himself, so we should do the same for him.",
  ui_story_5068_50680502_84_dialog_content = "Miss Rebecca?!",
  ui_story_5068_50680502_85_dialog_content = "That's my name—Rebecca Svanedona. And this is Eleanor.",
  ui_story_5068_50680502_86_dialog_content = "For certain reasons... We had to keep our names a secret.",
  ui_story_5068_50680502_87_dialog_content = "And yet you were willing to share them with me.",
  ui_story_5068_50680502_88_dialog_content = "That's because I believe you mean us no harm.",
  ui_story_5068_50680502_89_dialog_content = "In the books I read, the Caelestites were always described as a kind and peaceful race...",
  ui_story_5068_50680502_90_dialog_content = "Also... You don't appear to have any combat capabilities, so if you acted against us, I'd have no problem subduing you. Isn't that right?",
  ui_story_5068_50680502_91_dialog_content = "(For how gentle her tone is, there isn't a shred of compassion in her words... Even though she told me her name, she's still as distant as before.)",
  ui_story_5068_50680502_92_dialog_content = "So this guy's even weaker than he looks? Good, that's one less thing to worry about.",
  ui_story_5068_50680502_93_dialog_content = "I'm off to get rid of the scum littering our floor.",
  ui_story_5068_50680502_94_dialog_content = "Judging from what they said earlier, this place isn't safe anymore. It's possible...",
  ui_story_5068_50680502_95_dialog_content = "That we'll have to leave this place behind... And all of Umbraton too.",
  ui_story_5068_50680502_96_dialog_content = "If things get to that point—",
  ui_story_5068_50680502_97_dialog_content = "Don't worry... I'll make plans for the worst-case scenario.",
  ui_story_5068_50680502_98_dialog_content = "Also, you should stay in the hidden room until I get back.",
  ui_story_5068_50680502_99_dialog_content = "Don't let anyone in while I'm gone.",
  ui_story_5068_50680601_1_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5068_50680601_2_dialog_content = "... Alright, that should be the last of them.",
  ui_story_5068_50680601_3_dialog_content = "Hiss...",
  ui_story_5068_50680601_4_dialog_content = "Hmm? Waking up already, huh?",
  ui_story_5068_50680601_5_dialog_content = "You... what are you doing?!",
  ui_story_5068_50680601_6_dialog_content = "Huh? Where's this dump? Guys, wake up!",
  ui_story_5068_50680601_7_dialog_content = "... Hmm?",
  ui_story_5068_50680601_8_dialog_content = "What... what's happening?!",
  ui_story_5068_50680601_9_dialog_content = "Everyone, wake up! Hey, hey! Wake up now!",
  ui_story_5068_50680601_10_dialog_content = "My head... it's spinning. Why can't I remember anything?",
  ui_story_5068_50680601_11_dialog_content = "... This one in front of us must know something.",
  ui_story_5068_50680601_12_dialog_content = "Speak up! What were you sneaking around us for just now? Who's behind this?!",
  ui_story_5068_50680601_13_dialog_content = "Huh? How are they all awake so soon?",
  ui_story_5068_50680601_14_dialog_content = "Did Miss Rebecca give them a lower dosage to avoid any lasting side effects? Like I always say, she's way too kind of a person...",
  ui_story_5068_50680601_15_dialog_content = "What was she mumbling to herself all alone?",
  ui_story_5068_50680601_16_dialog_content = "Who cares? Let's go grab her!",
  ui_story_5068_50680601_17_dialog_content = "Hmph. Hate to disappoint you guys, but I'm not nearly as gentle as the doctor!",
  ui_story_5068_50680602_1_dialog_content = "—?!",
  ui_story_5068_50680602_2_dialog_content = "I'm not a doctor, so pardon me if I get the dosage wrong.",
  ui_story_5068_50680602_3_dialog_content = "But I promise, this injection will make you forget everything and have a new life. Sweet dreams, you trash.",
  ui_story_5068_50680602_4_dialog_content = "Huh?!",
  ui_story_5068_50680602_5_dialog_content = "You're the last one.",
  ui_story_5068_50680602_6_dialog_content = "Please... Please just let me go...",
  ui_story_5068_50680602_7_dialog_content = "Huh? Wait a second...",
  ui_story_5068_50680602_8_dialog_content = "Eleanor?",
  ui_story_5068_50680602_9_dialog_content = "Eleanor, it's you, right?! Don't, don't give me that shot! I know I'll be a goner if you do!",
  ui_story_5068_50680602_10_dialog_content = "It's not up to you.",
  ui_story_5068_50680602_11_dialog_content = "Don't! I'm begging you, Eleanor! For old-time's sake, please spare your friend!",
  ui_story_5068_50680602_12_dialog_content = "I took care of you so much in <color=#FFB400>all those years</color>!",
  ui_story_5068_50680602_13_dialog_content = "You know the rules, so just answer a few of my questions.",
  ui_story_5068_50680602_14_dialog_content = "Of course! Whatever you want! Just promise to let me go, and I'll tell you everything I know!",
  ui_story_5068_50680602_15_dialog_content = "What were you sent out to do?",
  ui_story_5068_50680602_16_dialog_content = "... What was I sent out to do today? I...",
  ui_story_5068_50680602_17_dialog_content = "Can't remember, huh?",
  ui_story_5068_50680602_18_dialog_content = "N-No, it's not that! Just give me a minute! No, thirty seconds!",
  ui_story_5068_50680602_19_dialog_content = "... I remember! I finally remember now!",
  ui_story_5068_50680602_20_dialog_content = "We... We were sent here to test out a newly developed...",
  ui_story_5068_50680602_21_dialog_content = "...",
  ui_story_5068_50680602_22_dialog_content = "If you can't tell me, I won't force it out of you.",
  ui_story_5068_50680602_23_dialog_content = "The <color=#FFB400>black mist</color>.",
  ui_story_5068_50680602_24_dialog_content = "We... We were sent here to test out the effects of a newly-developed black mist, and also...",
  ui_story_5068_50680602_25_dialog_content = "To track down a doctor who can treat its effects—Apparently, the <color=#FFB400>Director</color> is extremely interested in this person...",
  ui_story_5068_50680602_26_dialog_content = "A test? Of a new type of black mist?!",
  ui_story_5068_50680602_27_dialog_content = "Yes... And that's when we heard about a suspicious underground doctor. In fact, I'm pretty sure we were on our way to look for that doctor... So what are we doing here?",
  ui_story_5068_50680602_28_dialog_content = "Wait!",
  ui_story_5068_50680602_29_dialog_content = "What are you doing here too? And what are you—",
  ui_story_5068_50680602_30_dialog_content = "Sorry... Brother.",
  ui_story_5068_50680602_31_dialog_content = "You remember a little too much now.",
  ui_story_5068_50680602_32_dialog_content = "<color=#e8d9bb>Rustle, rustle...</color>",
  ui_story_5068_50680602_33_dialog_content = "Hoot—Hoot—",
  ui_story_5068_50680701_1_dialog_content = "<color=#e8d9bb>Tip-tap... Tip-tap...</color>",
  ui_story_5068_50680701_2_dialog_content = "Just a moment, please.",
  ui_story_5068_50680701_3_dialog_content = "<color=#e8d9bb>Click, click.</color>",
  ui_story_5068_50680701_4_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5068_50680701_5_dialog_content = "There. If you want to know more about the black mist, please come with me.",
  ui_story_5068_50680701_6_dialog_content = "But first, I must ask... That you keep everything you see and hear in this hidden room a secret.",
  ui_story_5068_50680701_7_dialog_content = "Of course, I promise.",
  ui_story_5068_50680701_8_dialog_content = "Please watch your step...",
  ui_story_5068_50680701_9_dialog_content = "We're here.",
  ui_story_5068_50680701_10_dialog_content = "—!!",
  ui_story_5068_50680701_11_dialog_content = "There... There are so many jars and bottles in here!",
  ui_story_5068_50680701_12_dialog_content = "I've been accumulating them for a long time without realizing it. Before I knew it, the room was full of specimens.",
  ui_story_5068_50680701_13_dialog_content = "Don't tell me these are all the...",
  ui_story_5068_50680701_14_dialog_content = "Some are and some aren't. There are even a number of them that have completely different effects.",
  ui_story_5068_50680701_15_dialog_content = "These jars and bottles contain the fruits of my research. By using my power on <color=#FFB400>different types of Lumina</color>, I can produce all kinds of serums with a wide variety of effects.",
  ui_story_5068_50680701_16_dialog_content = "<color=#FFB400>Different types of Lumina</color>?",
  ui_story_5068_50680701_17_dialog_content = "As you probably know by now, this clinic operates in the slums—Not everyone who comes here can pay for their treatment or medication with money.",
  ui_story_5068_50680701_18_dialog_content = "So for those patients with strong Lumina and empty wallets, I offer them the option of paying for my services with their Lumina.",
  ui_story_5068_50680701_19_dialog_content = "Are you familiar with this kind of situation? When it comes to research, there's nothing more important than having enough specimens and materials on hand.",
  ui_story_5068_50680701_20_dialog_content = "Don't worry, I've never forced anyone to comply with my work. Please trust me when I say that all of this Lumina was willingly provided by my patients or their family members.",
  ui_story_5068_50680701_21_dialog_content = "The Lumina I gather each time is also very small, and won't result in any long-term negative effects for Aurorians.",
  ui_story_5068_50680701_22_dialog_content = "But what exactly are you researching that would require so much Lumina?",
  ui_story_5068_50680701_23_dialog_content = "If it's to make and sell more stuff like that memory loss venom... I can't help but feel worried about this.",
  ui_story_5068_50680701_24_dialog_content = "I apologize for giving you that kind of impression. You must think... That I'm up to something terrible, right?",
  ui_story_5068_50680701_25_dialog_content = "All I know is that you're a good doctor whenever you're with your patients. There's no denying that.",
  ui_story_5068_50680701_26_dialog_content = "But I'm still curious to know about the goal of your \"research.\"",
  ui_story_5068_50680701_27_dialog_content = "The goal of my research...",
  ui_story_5068_50680701_28_dialog_content = "As a Caelestite, you should be able to use your special powers to read my mind, right?",
  ui_story_5068_50680701_29_dialog_content = "My \"special powers\" are actually a kind of psychic ability. I can only use them under dangerous circumstances.",
  ui_story_5068_50680701_30_dialog_content = "Psychic abilities... I see. Can they be used for anything else? Like immobilizing others, for example?",
  ui_story_5068_50680701_31_dialog_content = "Nothing like that, no. Aside from letting me pilot my Colossus and direct others in battle... They really can't be used for anything else.",
  ui_story_5068_50680701_32_dialog_content = "Your Colossus? Yes, I seem to recall something about the Caelestites having vehicles of that name.",
  ui_story_5068_50680701_33_dialog_content = "Soroz isn't just a vehicle; it's my closest and most important friend.",
  ui_story_5068_50680701_34_dialog_content = "\"Soroz\"? Is that what you call your Colossus? What an impressive-sounding name...",
  ui_story_5068_50680701_35_dialog_content = "If you ever have the time, I'd love to introduce you to Soroz someday. Lots of our friends like to come aboard to hang out all the time.",
  ui_story_5068_50680701_36_dialog_content = "Oh... Maybe someday, sure...",
  ui_story_5068_50680701_37_dialog_content = "Thank you for sharing so much about yourself and the Caelestites... I suppose I should share a few secrets about myself as well.",
  ui_story_5068_50680701_38_dialog_content = "The black mist, for starters.",
  ui_story_5068_50680701_39_dialog_content = "This black mist... is my family.",
  ui_story_5068_50680701_40_dialog_content = "... Your family?",
  ui_story_5068_50680701_41_dialog_content = "You mean to say you used your family's Lumina to make it...?",
  ui_story_5068_50680701_42_dialog_content = "No. This black mist is the <color=#FFB400>Svanedona Family's</color> unique method of... Existing.",
  ui_story_5068_50680701_43_dialog_content = "Perhaps you haven't heard but up until a year ago, the Svanedona Family was one of the most prominent and wealthy families in all of Umbraton.",
  ui_story_5068_50680701_44_dialog_content = "This family has a unique ability which is passed on from generation to generation: the power to create healing <color=#FFB400>serums</color> with their Lumina.",
  ui_story_5068_50680701_45_dialog_content = "And I happen to be one of their members.",
  ui_story_5068_50680701_46_dialog_content = "Aside from creating medical serums, I'm also capable of producing a highly dangerous type of <color=#FFB400>venom</color>. Whether it's a recessive gene or a gift from the divine is anyone's guess, although my family much prefers the latter explanation.",
  ui_story_5068_50680701_47_dialog_content = "In the past, I was completely ignorant of this venom's uses or its implications. After all, I always preferred using my powers to heal people, but then...",
  ui_story_5068_50680701_48_dialog_content = "...",
  ui_story_5068_50680701_49_dialog_content = "What's going on? Where am I?",
  ui_story_5068_50680701_50_dialog_content = "Rebecca? Rebecca! Are you there?",
  ui_story_5068_50680701_51_dialog_content = "I'm here, PlayerName. Please don't be afraid, I'm only using the mist to recreate my memories from that day...",
  ui_story_5068_50680701_52_dialog_content = "Look...",
  ui_story_5068_50680701_53_dialog_content = "The person on the floor is my uncle Albert. He was especially fond of hugging me when I was little, but I couldn't stand the prickly feeling of his beard.",
  ui_story_5068_50680701_54_dialog_content = "The little girl sitting over there is my cousin Jessica. She was always such a cute girl; I remember she'd carry a doll wherever she went, and it was just as cute as her. My older sister Isa really loved her too.",
  ui_story_5068_50680701_55_dialog_content = "Isa... my sister, also loved buying me expensive things all the time, even though I had no use for most of them. That day, I didn't even have the chance to see her face one last time.",
  ui_story_5068_50680701_56_dialog_content = "And over there... is my mother Lillian. I miss her so much. The stews that she made, the warmth of her embrace, and the smile on her face when she told me she loved me.",
  ui_story_5068_50680701_57_dialog_content = "But they're no longer a part of this world now.",
  ui_story_5068_50680701_58_dialog_content = "If Eleanor hadn't rescued me back then, I probably would have turned into the black mist just like them.",
  ui_story_5068_50680701_59_dialog_content = "The black mist... But didn't you say it was their unique form of existing?",
  ui_story_5068_50680701_60_dialog_content = "It is. When a member of the Svanedona Family dies and the Lumina completely leaves their body, the healing serum they used to produce deteriorates into a poisonous substance.",
  ui_story_5068_50680701_61_dialog_content = "And if that poison should come into contact with a hot enough fire...",
  ui_story_5068_50680701_62_dialog_content = "It becomes a black mist that can block out the sky.",
  ui_story_5068_50680701_63_dialog_content = "I sometimes wondered why I was born with the ability to produce this venom...",
  ui_story_5068_50680701_64_dialog_content = "When my family was attacked by the <color=#FFB400>Black Wolves</color>, I realized all too painfully how utterly powerless I was to protect them.",
  ui_story_5068_50680701_65_dialog_content = "It was the lowest and most hopeless moment of my life.",
  ui_story_5068_50680701_66_dialog_content = "So, you two have been hiding from the Black Wolves all along, huh...",
  ui_story_5068_50680701_67_dialog_content = "Allow me to answer your previous question. For the last year, I've been researching how to properly utilize my venom...",
  ui_story_5068_50680701_68_dialog_content = "I only have one goal: to protect the person I care about.",
  ui_story_5068_50680701_69_dialog_content = "And that would be Eleanor, right?",
  ui_story_5068_50680701_70_dialog_content = "Yes... She's all I have left now.",
  ui_story_5068_50680701_71_dialog_content = "But the black mist in your hand...",
  ui_story_5068_50680701_72_dialog_content = "I'm certain that it was created by a member of the Svanedona Family who met an untimely demise. What's more, it was created only recently!",
  ui_story_5068_50680701_73_dialog_content = "In other words...",
  ui_story_5068_50680701_74_dialog_content = "I have a proposition for you, PlayerName...",
  ui_story_5068_50680701_75_dialog_content = "I know what you're thinking. It's possible that some of your family members survived last year's attack, and that the Black Wolves are exploiting them as we speak...",
  ui_story_5068_50680701_76_dialog_content = "It looks like my investigation is making some progress after all.",
  ui_story_5068_50680701_77_dialog_content = "Don't worry, even though my job is to investigate the black mist, I'll definitely help you search for signs of your family.",
  ui_story_5068_50680701_78_dialog_content = "Thank you, PlayerName...",
  ui_story_5068_50680801_1_dialog_content = "Hoot—Hoot—",
  ui_story_5068_50680801_2_dialog_content = "Carefully search the area where Team B conducted their experiments! Their disappearance was no accident!",
  ui_story_5068_50680801_3_dialog_content = "Leave no stone unturned! No one rests until we flush out the culprits behind this!",
  ui_story_5068_50680801_4_dialog_content = "Yes, Director!",
  ui_story_5068_50680801_5_dialog_content = "Was it you, Rebecca? Even after an entire year... Are you still lurking in Umbraton? Do you honestly think you can look down on me like this? Or maybe...",
  ui_story_5068_50680801_6_dialog_content = "Hmm?",
  ui_story_5068_50680801_7_dialog_content = "<color=#e8d9bb>Tip-tap... Tip-tap...</color>",
  ui_story_5068_50680801_8_dialog_content = "Three... no, five of them... Maybe even more. They keep following me, and I can't get rid of them.",
  ui_story_5068_50680801_9_dialog_content = "Looks like one of those clowns managed to call for backup after all...",
  ui_story_5068_50680801_10_dialog_content = "Bring it on, cowards! Come out and fight!",
  ui_story_5068_50680802_1_dialog_content = "Wait... Stop! Stop it, all of you!",
  ui_story_5068_50680802_2_dialog_content = "You think I'm gonna stop just because you asked?!",
  ui_story_5068_50680802_3_dialog_content = "Open your eyes, Eleanor! It's me—Isa! Don't tell me you forgot about me?!",
  ui_story_5068_50680802_4_dialog_content = "Isa...?",
  ui_story_5068_50680802_5_dialog_content = "You're... You're still alive?!",
  ui_story_5068_50680802_6_dialog_content = "Not for long, if you don't stop attacking me!",
  ui_story_5068_50680802_7_dialog_content = "Eleanor? What's going on out here? I heard fighting, so I...",
  ui_story_5068_50680802_8_dialog_content = "—!!!",
  ui_story_5068_50680802_9_dialog_content = "It's... It's really you...",
  ui_story_5068_50680802_10_dialog_content = "Rebecca—!",
  ui_story_5068_50680802_11_dialog_content = "I've been looking everywhere for you for the last year!",
  ui_story_5068_50680802_12_dialog_content = "Thank goodness... Thank goodness you're still alive! I'm so glad I finally found you!!!",
  ui_story_5068_50680802_13_dialog_content = "... <color=#FFB400>Isa</color>?!",
  ui_story_5068_50680802_14_dialog_content = "No... I must be dreaming...",
  ui_story_5068_50680802_15_dialog_content = "This isn't a dream, Rebecca!",
  ui_story_5068_50680802_16_dialog_content = "But I thought I lost you that day too...",
  ui_story_5068_50680802_17_dialog_content = "Well as you can see, I'm perfectly fine! You, on the other hand... You've been through a lot, haven't you?",
  ui_story_5068_50680802_18_dialog_content = "(Isa? Isn't that Rebecca's older sister? Could this really be a coincidence?)",
  ui_story_5068_50680802_19_dialog_content = "(Also... Am I imagining things? It looks like the venom surrounding Rebecca is weakening as Isa gets closer to her.)",
  ui_story_5068_50680802_20_dialog_content = "And you must be PlayerName, right?",
  ui_story_5068_50680802_21_dialog_content = "Thanks to the information you provided, I was finally able to find my sister here... I really can't thank you enough!",
  ui_story_5068_50680802_22_dialog_content = "But I don't remember giving you—Wait, could it have been Lady Sheol?!",
  ui_story_5068_50680802_23_dialog_content = "Yep! Lady Sheol received your messages and recordings from earlier, but she hasn't been able to reach you ever since.",
  ui_story_5068_50680802_24_dialog_content = "Wow, no kidding! My terminal's full of messages from her! I must have been so caught up in the chaos that I forgot to check...",
  ui_story_5068_50680802_25_dialog_content = "So you're the assistant that Lady Sheol sent here?!",
  ui_story_5068_50680802_26_dialog_content = "That's right! I'm currently working for Lady Sheol and the Cloudrover Guild.",
  ui_story_5068_50680802_27_dialog_content = "A while back, I learned that the Black Wolves were searching for a girl who could treat the venomous effects of the black mist...",
  ui_story_5068_50680802_28_dialog_content = "Which led me to assume that my sister was still alive somewhere. That's when I asked Lady Sheol to help me keep an eye out.",
  ui_story_5068_50680802_29_dialog_content = "I've been helping her collect debts for the last few days, but when I heard about the black mist, I came back as fast as I could.",
  ui_story_5068_50680802_30_dialog_content = "As soon as I arrived, Lady Sheol told me that someone named PlayerName had made contact with an underground doctor, and that it was likely my sister Rebecca. Even if it wasn't her, the person was still closely tied to the Svanedona Family...",
  ui_story_5068_50680802_31_dialog_content = "So I gathered my team and rushed over here right away!",
  ui_story_5068_50680802_32_dialog_content = "Your... team?",
  ui_story_5068_50680802_33_dialog_content = "Heehee! The Cloudrover Guild was nice enough to—",
  ui_story_5068_50680802_34_dialog_content = "We should continue this conversation inside the clinic. It's not safe out here right now, and there's also the matter of what happened earlier...",
  ui_story_5068_50680802_35_dialog_content = "Not safe, you say? And what happened earlier?",
  ui_story_5068_50680802_36_dialog_content = "Everything's fine now, Isa. Let's just go inside.",
  ui_story_5068_50680802_37_dialog_content = "Huh? Okay, sure!",
  ui_story_5068_50680802_38_dialog_content = "Hey! Keep a close watch on the clinic and the surrounding area! No one comes in unless I give the order!",
  ui_story_5068_50680802_39_dialog_content = "Understood!",
  ui_story_5068_50680901_1_dialog_content = "... If I hadn't acted like such a stubborn brat towards our dad that day, I never would have stormed out of the house.",
  ui_story_5068_50680901_2_dialog_content = "But the moment I left, our house fell under attack...",
  ui_story_5068_50680901_3_dialog_content = "I really didn't know what to do on my own. I tried to reach out to some of our old acquaintances, but I ended up getting sold out by some rotten traitors!",
  ui_story_5068_50680901_4_dialog_content = "Sold out...?!",
  ui_story_5068_50680901_5_dialog_content = "Looking back, it was my fault for being so careless. By the time I finally caught on, I had already been surrounded... They put me through hell after that, but thankfully Lady Sheol showed up one day.",
  ui_story_5068_50680901_6_dialog_content = "She's such an incredible person! Not only did she save me, but she also gave me a job... That's why I want to repay her by working as hard as possible for her!",
  ui_story_5068_50680901_7_dialog_content = "I had no idea you went through so much in just a year's time...",
  ui_story_5068_50680901_8_dialog_content = "Hahaha! It's all in the past, so don't worry about it. Besides, didn't I say I was perfectly fine now?",
  ui_story_5068_50680901_9_dialog_content = "For me, it's like—How should I put it? Oh, right! I had to make my own luck!",
  ui_story_5068_50680901_10_dialog_content = "But let's talk about you, Rebecca! How'd you end up in a place like this?",
  ui_story_5068_50680901_11_dialog_content = "Everything's completely run-down around here. What's the world's cutest little sister doing running around in the slums?",
  ui_story_5068_50680901_12_dialog_content = "Eleanor! As Rebecca's maid, shouldn't you be taking better care of her?",
  ui_story_5068_50680901_13_dialog_content = "I—of course I've been taking good care of her! How could I possibly do otherwise?!",
  ui_story_5068_50680901_14_dialog_content = "Rebecca's the most important person in the world to me. Even if it cost me my life, I would—",
  ui_story_5068_50680901_15_dialog_content = "Then why haven't you found a better place for her to live? This place is absolutely unacceptable!",
  ui_story_5068_50680901_16_dialog_content = "Isa, I know you're only worried about me... But please don't blame her.",
  ui_story_5068_50680901_17_dialog_content = "She's not a servant of the Svanedona Family anymore, and... we're not the daughters of nobles anymore either.",
  ui_story_5068_50680901_18_dialog_content = "If it wasn't for Eleanor, I would've... In any case, she rescued me and she's been doing her best to keep me safe from the Black Wolves for the last year.",
  ui_story_5068_50680901_19_dialog_content = "It wasn't easy for her to find this \"run-down\" clinic and fix it up either.",
  ui_story_5068_50680901_20_dialog_content = "It may not be the fanciest, but it keeps us safe from the elements.",
  ui_story_5068_50680901_21_dialog_content = "We live as the doctor and the assistant here, and I cherish the new life we've built together.",
  ui_story_5068_50680901_22_dialog_content = "Miss Rebecca...",
  ui_story_5068_50680901_23_dialog_content = "Besides, living here isn't all that bad.",
  ui_story_5068_50680901_24_dialog_content = "When we don't have as many patients, we grow flowers and make handicrafts just like we used to...",
  ui_story_5068_50680901_25_dialog_content = "See? Eleanor made these earrings for me with her own two hands!",
  ui_story_5068_50680901_26_dialog_content = "They look pretty average... Er, I mean, if it was me, I would've made you an even better-looking set.",
  ui_story_5068_50680901_27_dialog_content = "I used to buy things for you all the time. If anyone knows what suits you best, it's me!",
  ui_story_5068_50680901_28_dialog_content = "...",
  ui_story_5068_50680901_29_dialog_content = "Yes, yes, I know. You really do have an eye for this kind of stuff.",
  ui_story_5068_50680901_30_dialog_content = "*Coughs*",
  ui_story_5068_50680901_31_dialog_content = "Hmm? Do you have something to say, PlayerName?",
  ui_story_5068_50680901_32_dialog_content = "N-Not really! It just feels like Rebecca is the older sister here...",
  ui_story_5068_50680901_33_dialog_content = "Huh? Why does everyone keep saying that? Even our family members used to...",
  ui_story_5068_50680901_34_dialog_content = "... Isa, do you think any of our family members are still out there?",
  ui_story_5068_50680901_35_dialog_content = "I was gonna ask you the exact same question. Looks like neither of us knows, huh?",
  ui_story_5068_50680901_36_dialog_content = "Lady Sheol gave me a false identity, so the Black Wolves haven't been able to find me... I've only heard of them trying to hunt you down, not any of our other family members.",
  ui_story_5068_50680901_37_dialog_content = "I was under the impression that everyone was lost in last year's attack. It wasn't until PlayerName showed me that bottle of black mist that I realized someone in our family was only recently...",
  ui_story_5068_50680901_38_dialog_content = "Still... that also means there might be other Svanedonas out there, right?",
  ui_story_5068_50680901_39_dialog_content = "It's also possible that they're on the run from the Black Wolves, just like us. Some of them might have gotten captured and exploited too...",
  ui_story_5068_50680901_40_dialog_content = "Don't worry, Rebecca. I promise I'll help you find them no matter what!",
  ui_story_5068_50680901_41_dialog_content = "Before we continue our investigation, I suggest we change locations as soon as possible. The clinic isn't safe anymore.",
  ui_story_5068_50680901_42_dialog_content = "The Black Wolves... Even after attacking our entire family a year ago, they still haven't given up the hunt? What could they possibly want from us?",
  ui_story_5068_50680901_43_dialog_content = "If Lady Sheol hadn't stopped me, I'd have already gone to settle the score with them!",
  ui_story_5068_50680901_44_dialog_content = "I may not know this \"Lady Sheol\" you keep mentioning, but I think she has the right idea. Taking on the Black Wolves all by yourself is incredibly dangerous.",
  ui_story_5068_50680901_45_dialog_content = "But what about now? I have you, as well as plenty of people in the Cloudrover Guild to help me out. Sooner or later, I'm gonna collect the debt that the Black Wolves owe the Svanedona Family!",
  ui_story_5068_50680901_46_dialog_content = "That's right! If you need a new place to hide from the Black Wolves, why not come to the Cloudrover Guild with me?",
  ui_story_5068_50680901_47_dialog_content = "I think that's a great idea!",
  ui_story_5068_50680901_48_dialog_content = "Lady Sheol's the one who hired me for this, and everyone here is closely connected to the black mist. I'm sure she'll offer you the best protection the guild can buy.",
  ui_story_5068_50680901_49_dialog_content = "But...",
  ui_story_5068_50680901_50_dialog_content = "Hmm? Is something on your mind, Rebecca?",
  ui_story_5068_50680901_51_dialog_content = "I'm sure she's worried about dragging Lady Sheol and the Cloudrover Guild into our problems... As well as you, Isa.",
  ui_story_5068_50680901_52_dialog_content = "What? But we're family! I'd never be upset about something like that, and neither would Lady Sheol! She's a good person, I'm sure she won't mind!",
  ui_story_5068_50680901_53_dialog_content = "No matter how vicious the Black Wolves may be, they'd be crazy to make enemies with the Cloudrover Guild. When the time is right, we can use the guild's power to crush them and avenge our family!",
  ui_story_5068_50680901_54_dialog_content = "Revenge... Is never that simple. I just want to keep living in peace... with you and Eleanor by my side.",
  ui_story_5068_50680901_55_dialog_content = "I know, Rebecca, but the world isn't that simple.",
  ui_story_5068_50680901_56_dialog_content = "I know you don't want to hurt anyone, but that doesn't matter to them! People will find all sorts of reasons to hurt you!",
  ui_story_5068_50680901_57_dialog_content = "I never wanted to show you the cruelty of our world, but regardless of what we want, we need to face reality head-on right now!",
  ui_story_5068_50680901_58_dialog_content = "It's totally unreasonable, right?",
  ui_story_5068_50680901_59_dialog_content = "But that's just how things are: the strong eat the weak, and only the fittest survive. If we don't make the first move—",
  ui_story_5068_50680901_60_dialog_content = "Enough already! There's no need to keep badgering her about this anymore!",
  ui_story_5068_50680901_61_dialog_content = "She's always been a kind and gentle person. As long as she can stay this way, I'll take care of everything else myself!",
  ui_story_5068_50680901_62_dialog_content = "You? But there's only so much you can do! Some things need to be decided by her and no one else! You can't expect to be at her side every minute of every day!",
  ui_story_5068_50680901_63_dialog_content = "I can and I will! That's exactly what I've been doing for the last year!",
  ui_story_5068_50680901_64_dialog_content = "Calm down, everyone! Now's not the time to argue...",
  ui_story_5068_50680901_65_dialog_content = "I still think Isa has the right idea, Rebecca—If you're concerned for your safety, the Cloudrover Guild is a good place to set up camp.",
  ui_story_5068_50680901_66_dialog_content = "What do you think, Eleanor?",
  ui_story_5068_50680901_67_dialog_content = "I'll go with whatever you decide, Miss Rebecca.",
  ui_story_5068_50680901_68_dialog_content = "I see... There's no time to hesitate, so it seems we'll have to impose on the Cloudrover Guild for the time being.",
  ui_story_5068_50680901_69_dialog_content = "Good! Now that we've decided, let's get moving right away!",
  ui_story_5068_50680901_70_dialog_content = "I just need a moment to gather a few things. Give me a hand, Eleanor.",
  ui_story_5068_50680901_71_dialog_content = "Yes, Miss Rebecca.",
  ui_story_5068_50680901_72_dialog_content = "Then let me—",
  ui_story_5068_50680901_73_dialog_content = "Eleanor is more than enough help, Isa. She's familiar with the things I need, so please... Just make yourself comfortable for now.",
  ui_story_5068_50680901_74_dialog_content = "Eleanor again... Hmph. What could she know about Rebecca that her own sister doesn't know?!",
  ui_story_5068_50680901_75_dialog_content = "Hey! Who are you and what's your business here?!",
  ui_story_5068_50680901_76_dialog_content = "Huh? What's with the sudden ruckus outside?",
  ui_story_5068_50680901_77_dialog_content = "Hey! What's happening out there?!",
  ui_story_5068_50680901_78_dialog_content = "*coughing* Urgh—It's... It's the black mist! Someone released it into the air!",
  ui_story_5068_50680901_79_dialog_content = "This is bad! Let's go check it out!",
  ui_story_5068_50680901_80_dialog_content = "Who could have released so much black mist over here...",
  ui_story_5068_50680901_81_dialog_content = "Was it the Black Wolves?!",
  ui_story_5068_50680901_82_dialog_content = "*coughing* It feels awful...!",
  ui_story_5068_50680901_83_dialog_content = "Over here, everyone! Quickly!",
  ui_story_5068_50680901_84_dialog_content = "Rebecca? When did you come out?",
  ui_story_5068_50680901_85_dialog_content = "I heard a commotion outside just now. Here, this serum should greatly lessen the effects of the black mist. Everyone, come here and take some for yourselves!",
  ui_story_5068_50680901_86_dialog_content = "Target spotted!",
  ui_story_5068_50680901_87_dialog_content = "...!!",
  ui_story_5068_50680901_88_dialog_content = "Get lost! I won't let any of you lay a finger on Miss Rebecca!",
  ui_story_5068_50680902_1_dialog_content = "Is everyone all right?",
  ui_story_5068_50680902_2_dialog_content = "Thanks to your serum, I feel much better.",
  ui_story_5068_50680902_3_dialog_content = "This black mist... It seems a lot more potent than the stuff Lady Sheol gave me earlier.",
  ui_story_5068_50680902_4_dialog_content = "...",
  ui_story_5068_50680902_5_dialog_content = "This isn't good, Isa!",
  ui_story_5068_50680902_6_dialog_content = "What happened now?",
  ui_story_5068_50680902_7_dialog_content = "Look outside... A bunch of slum-dwellers are starting to surround this place!",
  ui_story_5068_50680902_8_dialog_content = "Slum-dwellers? But what are they doing here?",
  ui_story_5068_50680902_9_dialog_content = "Oh no...!",
  ui_story_5068_50680902_10_dialog_content = "Hold it! You're not allowed to come inside!",
  ui_story_5068_50680902_11_dialog_content = "Who... Who are you people? Where's the doctor? *cough, cough* We need her help... All this black mist suddenly appeared, and everyone...",
  ui_story_5068_50680902_12_dialog_content = "Urgh... It hurts so much... Where's the doctor...?",
  ui_story_5068_50680902_13_dialog_content = "There are so many people, and some of them have already passed out...",
  ui_story_5068_50680902_14_dialog_content = "Eleanor! Everyone! I... I need your help!",
  ui_story_5068_50680902_15_dialog_content = "Yes, Miss Rebecca!",
  ui_story_5068_50680902_16_dialog_content = "Huh?",
  ui_story_5068_50680902_17_dialog_content = "Quit your griping! You heard her, now go lend a hand!",
  ui_story_5068_50680902_18_dialog_content = "Please don't panic, everyone! Keep your distance from each other and avoid trampling on the unconscious!",
  ui_story_5068_50680902_19_dialog_content = "... They all came looking for help. I refuse to abandon any of them!",
  ui_story_5068_50680902_20_dialog_content = "Rebecca? What are you...",
  ui_story_5068_50680902_21_dialog_content = "There's no time, so I'll just have to treat them all at once...",
  ui_story_5068_50680902_22_dialog_content = "Wait, you're going to treat this many people at the same time? Can your body handle that?!",
  ui_story_5068_50680902_23_dialog_content = "Haaaa—!!",
  ui_story_5068_50680902_24_dialog_content = "*coughs* It's getting... easier to breathe...",
  ui_story_5068_50680902_25_dialog_content = "The doctor... she saved us again...",
  ui_story_5068_50680902_26_dialog_content = "...",
  ui_story_5068_50680902_27_dialog_content = "Miss Rebecca!!!",
  ui_story_5068_50680902_28_dialog_content = "Hey! Quit scaring me like this! Rebecca?!",
  ui_story_5068_50680902_29_dialog_content = "Is... Is everyone alright now? I'm a little... out of breath. Eleanor, go check on them for me...",
  ui_story_5068_50680902_30_dialog_content = "Rebecca, I—",
  ui_story_5068_50680902_31_dialog_content = "Go!",
  ui_story_5068_50680902_32_dialog_content = "...",
  ui_story_5068_50680902_33_dialog_content = "Hey! Rebecca? Rebecca?!",
  ui_story_5068_50680902_34_dialog_content = "Stop shaking her! She burned through too much Lumina, so she's extremely delicate right now. We need to find a safe place for her to recover!",
  ui_story_5068_50680902_35_dialog_content = "I... I'm fine. Eleanor, are the others—",
  ui_story_5068_50680902_36_dialog_content = "They're fine for now, Miss Rebecca. Thanks to your treatment, all they need is some rest to make a full recovery.",
  ui_story_5068_50680902_37_dialog_content = "... Is that so? What a relief.",
  ui_story_5068_50680902_38_dialog_content = "Have the Black Wolves completely lost their minds?! How could they do something so horrible?!",
  ui_story_5068_50680902_39_dialog_content = "They may have another goal in mind.",
  ui_story_5068_50680902_40_dialog_content = "... They're trying to force Miss Rebecca out of hiding!",
  ui_story_5068_50680902_41_dialog_content = "Argh... This place is completely compromised now!",
  ui_story_5068_50680902_42_dialog_content = "Then let's head over to the Cloudrover Guild. I can't think of a safer place to go right now.",
  ui_story_5068_50680902_43_dialog_content = "Got it! I'll carry Rebecca!",
  ui_story_5068_50680902_44_dialog_content = "No, leave that to me.",
  ui_story_5068_50680902_45_dialog_content = "You... fine! But be careful!",
  ui_story_5068_50680902_46_dialog_content = "...",
  ui_story_5068_50680902_47_dialog_content = "As for you guys, stay here and keep a handle on things. Once these people have recovered, send them home right away!",
  ui_story_5068_50680902_48_dialog_content = "Yes!",
  ui_story_5068_50681001_1_dialog_content = "Director...",
  ui_story_5068_50681001_2_dialog_content = "We've confirmed Rebecca's presence in the area where Team B disappeared, but...",
  ui_story_5068_50681001_3_dialog_content = "I taught you better than to mince words, now out with it.",
  ui_story_5068_50681001_4_dialog_content = "It's just that her venom attacks make it difficult for us to approach her... Much less capture her alive.",
  ui_story_5068_50681001_5_dialog_content = "... She really does have a gift if she learned to control her venom in just a single year.",
  ui_story_5068_50681001_6_dialog_content = "But you're still much stronger than her, Director. After all, you created a black mist that <color=#FFB400>specifically counters her venom</color>!",
  ui_story_5068_50681001_7_dialog_content = "That's none of your concern.",
  ui_story_5068_50681001_8_dialog_content = "F-Forgive me, Director! I'll just keep my mouth shut...",
  ui_story_5068_50681001_9_dialog_content = "So, where's Rebecca right now?",
  ui_story_5068_50681001_10_dialog_content = "We found her at her Underground Clinic, but she had some allies at her side. They're taking her to the Cloudrover Guild as we speak.",
  ui_story_5068_50681001_11_dialog_content = "But the thing is, it's just not the right time yet to take them on.",
  ui_story_5068_50681001_12_dialog_content = "The Cloudrover Guild?",
  ui_story_5068_50681001_13_dialog_content = "That does make things more difficult, but we still have other options.",
  ui_story_5068_50681001_14_dialog_content = "Alright, we should be safe now that we made it to the Cloudrover Guild.",
  ui_story_5068_50681001_15_dialog_content = "Are you feeling better now, Rebecca?",
  ui_story_5068_50681001_16_dialog_content = "Yes... Sorry for troubling everyone just now.",
  ui_story_5068_50681001_17_dialog_content = "You don't need to be so polite to me! The Cloudrover Guild's on our turf, so just lay down and relax while we take care of the rest!",
  ui_story_5068_50681001_18_dialog_content = "Looks like this room is still missing a few supplies, but don't worry! I'll just go buy some for you!",
  ui_story_5068_50681001_19_dialog_content = "Wait, Isa... It's too dangerous to leave right now, isn't it?",
  ui_story_5068_50681001_20_dialog_content = "Like I said, this is the Cloudrover Guild, so the Black Wolves would have to be really stupid to pick a fight with us here. Don't worry, I'll be back before you know it!",
  ui_story_5068_50681001_21_dialog_content = "PlayerName... You don't look so well... Are you feeling alright?",
  ui_story_5068_50681001_22_dialog_content = "I'm fine. This job turned out to be a lot more complicated than I thought, that's all...",
  ui_story_5068_50681001_23_dialog_content = "But don't worry, I just need some time to think. Go ahead and get some rest.",
  ui_story_5068_50681001_24_dialog_content = "I'm sorry for... making so much trouble for you...",
  ui_story_5068_50681001_25_dialog_content = "Hmm...",
  ui_story_5068_50681001_26_dialog_content = "...!!!",
  ui_story_5068_50681001_27_dialog_content = "Eleanor... Hurry...",
  ui_story_5068_50681001_28_dialog_content = "PlayerName, you can leave now.",
  ui_story_5068_50681001_29_dialog_content = "Huh? B-But Rebecca is...",
  ui_story_5068_50681001_30_dialog_content = "I said leave! Rebecca needs her rest right now!",
  ui_story_5068_50681001_31_dialog_content = "Geez, I almost forgot to ask! Hey, Rebecca, what exactly do you need me to—",
  ui_story_5068_50681001_32_dialog_content = "Err...",
  ui_story_5068_50681001_33_dialog_content = "R-Rebecca...? Wha-What's going on here?!",
  ui_story_5068_50681001_34_dialog_content = "Isa... Please... Don't look...",
  ui_story_5068_50681001_35_dialog_content = "Err...",
  ui_story_5068_50681001_36_dialog_content = "Is this... the venom?!",
  ui_story_5068_50681001_37_dialog_content = "But... why is there venom seeping out of your skin? It's... It's starting to turn bright red! We need to wipe it off your skin right away!",
  ui_story_5068_50681001_38_dialog_content = "Don't touch her!",
  ui_story_5068_50681001_39_dialog_content = "Don't touch her?! My sister's in pain, now let go of me! How can you just stand there and watch?!",
  ui_story_5068_50681001_40_dialog_content = "I don't want to see Rebecca in pain either! But right now...",
  ui_story_5068_50681001_41_dialog_content = "There's nothing we can do to help her.",
  ui_story_5068_50681001_42_dialog_content = "Rebecca produced way too much serum earlier. The only way for her to restabilize is by expelling this much venom.",
  ui_story_5068_50681001_43_dialog_content = "If the balance between the two is broken... It's likely that she'll lose her sanity.",
  ui_story_5068_50681001_44_dialog_content = "What's more, this venom is extremely dangerous for most people. I'm sure she doesn't want anyone to come into contact with it!",
  ui_story_5068_50681001_45_dialog_content = "Uh...",
  ui_story_5068_50681001_46_dialog_content = "Rebecca...",
  ui_story_5068_50681001_47_dialog_content = "But she never had to do this before! I'm her big sister, so how come I never knew about this?!",
  ui_story_5068_50681001_48_dialog_content = "It's something that she decided to shoulder by herself. She has her reasons for doing this too.",
  ui_story_5068_50681001_49_dialog_content = "I don't care about her reasons! You can't just let Rebecca hurt herself like this!",
  ui_story_5068_50681001_50_dialog_content = "V-Veronica...",
  ui_story_5068_50681001_51_dialog_content = "I... I chose this for myself, Isa. It's my burden to bear... So don't blame anyone else.",
  ui_story_5068_50681001_52_dialog_content = "I didn't want... you to worry too much. But you still... found out.",
  ui_story_5068_50681001_53_dialog_content = "Rebecca! Are... Are you feeling better?",
  ui_story_5068_50681001_54_dialog_content = "Yes... Once I get all of this out of my system... I feel much better.",
  ui_story_5068_50681001_55_dialog_content = "Is this what you kept in all those jars back in your hidden room? If so, that means you've gone through this plenty of times...",
  ui_story_5068_50681001_56_dialog_content = "What jars? And hidden room?! If you don't want me to worry, then tell me everything!",
  ui_story_5068_50681001_57_dialog_content = "It's... really not that big of a problem. It's just that... Ever since <color=#FFB400>that day</color>, I decided to conduct research on my venom.",
  ui_story_5068_50681001_58_dialog_content = "Maybe it's because I started too late, or maybe I was in too much of a rush, but... My research resulted in these side effects.",
  ui_story_5068_50681001_59_dialog_content = "But I'm not going to stop.",
  ui_story_5068_50681001_60_dialog_content = "Back then... I wasn't able to use my \"gift\" to help anyone. All I could do was run and hide like a coward...",
  ui_story_5068_50681001_61_dialog_content = "That wasn't your fault, Rebecca! The Black Wolves are to blame, not you!",
  ui_story_5068_50681001_62_dialog_content = "But... But if I had learned to control my venom sooner, I might have been able to keep them from breaking into our home...",
  ui_story_5068_50681001_63_dialog_content = "Even now, I still have people I want to protect.",
  ui_story_5068_50681001_64_dialog_content = "And if protecting them means putting up with a little more pain... Then it's a price I'm willing to pay.",
  ui_story_5068_50681001_65_dialog_content = "That didn't look like a little more pain just now. You were clearly suffering... Argh, what kind of useless sister am I?!",
  ui_story_5068_50681001_66_dialog_content = "You shouldn't have to do this... That's right! You won't have to do this anymore!",
  ui_story_5068_50681001_67_dialog_content = "I'll just ask Lady Sheol to offer you a job in the guild. Once she returns from her business meeting, I'll put in a good word for you!",
  ui_story_5068_50681001_68_dialog_content = "That way you can live and work in total safety! You'll never have to fear for your life ever again, or hurt yourself with any more of your research!",
  ui_story_5068_50681001_69_dialog_content = "As for the details, just leave the rest to me!",
  ui_story_5068_50681001_70_dialog_content = "Isa... Even after all this time, you still see me as a child.",
  ui_story_5068_50681001_71_dialog_content = "That's what big sisters do! Don't worry, I know just what to do!",
  ui_story_5068_50681001_72_dialog_content = "I'll go buy you a nice pair of pajamas while you get lots of rest. See you in a bit!",
  ui_story_5068_50681001_73_dialog_content = "...",
  ui_story_5068_50681001_74_dialog_content = "Is something still troubling you, Miss Rebecca?",
  ui_story_5068_50681001_75_dialog_content = "I can't stop worrying about those patients from earlier. We left in such a hurry that I wasn't able to assess any of them more closely.",
  ui_story_5068_50681001_76_dialog_content = "We're not at the clinic anymore, so if anything happens to them...",
  ui_story_5068_50681001_77_dialog_content = "Don't worry, I'll go back and check on them. We left a few medical supplies behind, so I can distribute those as well.",
  ui_story_5068_50681001_78_dialog_content = "You're leaving right now? But what if the Black Wolves are still lurking around the clinic?",
  ui_story_5068_50681001_79_dialog_content = "You're not underestimating me, are you, PlayerName?",
  ui_story_5068_50681001_80_dialog_content = "In any case, I'm still not comfortable with leaving you alone in the Cloudrover Guild, Miss Rebecca.",
  ui_story_5068_50681001_81_dialog_content = "This place seems safe enough. Besides, PlayerName is still here and my sister should be back soon.",
  ui_story_5068_50681001_82_dialog_content = "I feel a lot better now, but the same can't be said for our patients. They need us right now.",
  ui_story_5068_50681001_83_dialog_content = "Understood. I won't be long, but please take good care of yourself while I'm away.",
  ui_story_5068_50681001_84_dialog_content = "Rebecca seems to trust you, PlayerName, so I'll do the same.",
  ui_story_5068_50681001_85_dialog_content = "Okay.",
  ui_story_5068_50681001_86_dialog_content = "I'm sorry, PlayerName... I didn't scare you just now, did I?",
  ui_story_5068_50681001_87_dialog_content = "Not at all. Please don't feel that way.",
  ui_story_5068_50681001_88_dialog_content = "It's just... could you promise me something?",
  ui_story_5068_50681001_89_dialog_content = "What is it?",
  ui_story_5068_50681001_90_dialog_content = "No matter what happens, please don't hurt yourself ever again.",
  ui_story_5068_50681001_91_dialog_content = "PlayerName...",
  ui_story_5068_50681001_92_dialog_content = "Let's see... She definitely needs stuff for bathing, as well as a towel... Ah, I'll just buy her a bunch of towels!",
  ui_story_5068_50681001_93_dialog_content = "Wow, I bet Rebecca would look super cute in this! Now I just need...",
  ui_story_5068_50681001_94_dialog_content = "?!",
  ui_story_5068_50681001_95_dialog_content = "*cough, cough* Who's there? And how dare you make trouble... on the Cloudrover Guild's turf?!",
  ui_story_5068_50681001_96_dialog_content = "<color=#e8d9bb>Poof—</color>",
  ui_story_5068_50681001_97_dialog_content = "Huh...?!",
  ui_story_5068_50681001_98_dialog_content = "The Black Wolves...",
  ui_story_5068_50681101_1_dialog_content = "Wait... Where am I?",
  ui_story_5068_50681101_2_dialog_content = "And I'm all tied up?! Tsk, those Black Wolves always resort to such lowly tricks.",
  ui_story_5068_50681101_3_dialog_content = "Still, the way they tied me up... Heh, your ancestors must be so ashamed.",
  ui_story_5068_50681101_4_dialog_content = "...",
  ui_story_5068_50681101_5_dialog_content = "What's the matter now? Can't talk to a girl even after you kidnap her?!",
  ui_story_5068_50681101_6_dialog_content = "Tell whoever's in charge to get out here! I have a score to settle with them!",
  ui_story_5068_50681101_7_dialog_content = "Isa Svanedona, the eldest daughter of the Svanedona Family who happened to be studying abroad at the time.",
  ui_story_5068_50681101_8_dialog_content = "I wonder what kind of black mist your body will produce when it burns... Will it cause people unbearable pain? Or maybe it'll give them uncontrollable convulsions?",
  ui_story_5068_50681101_9_dialog_content = "Heheheh. What a shame that you didn't inherit your family's gifts.",
  ui_story_5068_50681101_10_dialog_content = "Shut your mouth! My family may be gone but I'm still here, and I'll get my revenge sooner or later!",
  ui_story_5068_50681101_11_dialog_content = "Really? Because you don't seem to be good at anything besides talking big. Your sister, on the other hand...",
  ui_story_5068_50681101_12_dialog_content = "What do you want with her?! I won't let the Black Wolves hurt any more of my family!",
  ui_story_5068_50681101_13_dialog_content = "What do I want? Heh... All I want is to finish what I started.",
  ui_story_5068_50681101_14_dialog_content = "I'm warning you, stay away from my sister... Or else...",
  ui_story_5068_50681101_15_dialog_content = "Or else what? Wait, let me guess... You're going to break free from your bindings and kill me where I stand?",
  ui_story_5068_50681101_16_dialog_content = "Urgh...! Shut up!",
  ui_story_5068_50681102_1_dialog_content = "I-If you want to get to my sister... You'll have to kill me first...",
  ui_story_5068_50681102_2_dialog_content = "Kill you? Please, I'm not stupid enough to face the Cloudrover Guild head-on.",
  ui_story_5068_50681102_3_dialog_content = "Maybe you're not stupid enough... But you're still plenty stupid... Hahaha...",
  ui_story_5068_50681102_4_dialog_content = "That's enough out of you!",
  ui_story_5068_50681102_5_dialog_content = "When you're up against overwhelming power, all you can do is roll over and die... After all my years of fighting, that's the only truth I've come to learn.",
  ui_story_5068_50681102_6_dialog_content = "And now, I'm about to teach you the very same lesson... You should feel grateful.",
  ui_story_5068_50681102_7_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5068_50681102_8_dialog_content = "Is that you, Isa?",
  ui_story_5068_50681102_9_dialog_content = "No... That's weird, there's no one at the door.",
  ui_story_5068_50681102_10_dialog_content = "Huh? There's a letter on the ground... And it says \"To Rebecca\"!",
  ui_story_5068_50681102_11_dialog_content = "For me? Let me see...",
  ui_story_5068_50681102_12_dialog_content = "No... This can't be!",
  ui_story_5068_50681102_13_dialog_content = "It's Isa... She's been captured by the Black Wolves! But she said they wouldn't do anything to her on the Cloudrover Guild's turf!",
  ui_story_5068_50681102_14_dialog_content = "If the Black Wolves are willing to ignore Umbraton's rules... It means they're ready to fight in the open now.",
  ui_story_5068_50681102_15_dialog_content = "Eleanor's still not back... could something have happened to her too?",
  ui_story_5068_50681102_16_dialog_content = "We'll worry about that later. What else does the letter say?",
  ui_story_5068_50681102_17_dialog_content = "It says that if we want her to stay unharmed, I need to show up at their hideout in the next hour... There's also an address written here.",
  ui_story_5068_50681102_18_dialog_content = "So they were after you all along. You'd be playing right into their hands if you went over there right now!",
  ui_story_5068_50681102_19_dialog_content = "But they kidnapped Isa... I don't have a choice!",
  ui_story_5068_50681102_20_dialog_content = "How could I possibly abandon her when we just found each other after all this time? Not only that, there might be more of my family there...",
  ui_story_5068_50681102_21_dialog_content = "But I promised to find a way to help you...",
  ui_story_5068_50681102_22_dialog_content = "There's no time anymore... For the last year, I've done nothing but run and hide in my underground clinic.",
  ui_story_5068_50681102_23_dialog_content = "I had no way of knowing if anyone in my family survived, or if they had been captured and tortured... My cowardice is what caused all of this.",
  ui_story_5068_50681102_24_dialog_content = "In spite of that, I'm still just running away. I... I even asked you to think of an answer for me.",
  ui_story_5068_50681102_25_dialog_content = "The whole point of researching my venom was to find a way to protect the ones I care about, but not only did I fail, I also put my sister's life at risk...",
  ui_story_5068_50681102_26_dialog_content = "I can't keep running away. Not anymore.",
  ui_story_5068_50681102_27_dialog_content = "If your loved ones got kidnapped, you'd stop at nothing to rescue them right?",
  ui_story_5068_50681102_28_dialog_content = "... I knew I wouldn't be able to talk you out of it, but this is way too dangerous for just the two of us.",
  ui_story_5068_50681102_29_dialog_content = "The Cloudrover Guild... Umbraton... Even gangs...",
  ui_story_5068_50681102_30_dialog_content = "Wait—I know a mercenary group here in the city! Maybe they can help us out!",
  ui_story_5068_50681201_1_dialog_content = "I never imagined you would accept a job that involved rescuing a hostage, PlayerName.",
  ui_story_5068_50681201_2_dialog_content = "It's a long story... But we have to get Isa out of there safely.",
  ui_story_5068_50681201_3_dialog_content = "Thanks for showing up on such short notice, by the way. This should help us out a lot!",
  ui_story_5068_50681201_4_dialog_content = "Don't worry about it! Captain Luke couldn't make it here personally, but we'll give it everything we've got!",
  ui_story_5068_50681201_5_dialog_content = "We're in the Black Wolves' hideout, so stay on your toes! The black mist is especially dense here, which means they're probably producing it somewhere in this place!",
  ui_story_5068_50681201_6_dialog_content = "...",
  ui_story_5068_50681201_7_dialog_content = "<color=#e8d9bb>Creeaaak...</color>",
  ui_story_5068_50681201_8_dialog_content = "Do you really think Isa is in here? All I see is a bunch of jars and containers.",
  ui_story_5068_50681201_9_dialog_content = "I can sense Isa's presence nearby, but these jars...",
  ui_story_5068_50681201_10_dialog_content = "There are names written on them...",
  ui_story_5068_50681201_11_dialog_content = "Uncle Albert, Jessica... Mom and Dad... Aaron...",
  ui_story_5068_50681201_12_dialog_content = "Their names are on these jars of venom, which means they're all...",
  ui_story_5068_50681201_13_dialog_content = "Rebecca...",
  ui_story_5068_50681201_14_dialog_content = "All of these names...",
  ui_story_5068_50681201_15_dialog_content = "There's even... There's even a big, empty jar with my name on it.",
  ui_story_5068_50681201_16_dialog_content = "... B-But I don't see one with Isa's name! That means we're not too late!",
  ui_story_5068_50681201_17_dialog_content = "No, PlayerName. You see... Isa never inherited our family's ability.",
  ui_story_5068_50681201_18_dialog_content = "Which means she might already be...",
  ui_story_5068_50681201_19_dialog_content = "Don't jump to conclusions just yet. We still have to find her first!",
  ui_story_5068_50681201_20_dialog_content = "Look out! The enemy's approaching!",
  ui_story_5068_50681201_21_dialog_content = "<color=#e8d9bb>Knock, knock, knock...</color>",
  ui_story_5068_50681201_22_dialog_content = "On behalf of the Black Wolves, welcome to our base of operations.",
  ui_story_5068_50681201_23_dialog_content = "... It's Arte, the Director of the Black Wolves!",
  ui_story_5068_50681201_24_dialog_content = "Heheh... It's been some time since this place has seen any action.",
  ui_story_5068_50681201_25_dialog_content = "It's rude to bring a crowd to the party when I only invited you... Rebecca Svanedona.",
  ui_story_5068_50681201_26_dialog_content = "What a pity. If you had gotten here a little earlier, you might've had the chance to see him one last time... Your father, I believe? The man had unbelievable resolve; out of all my test subjects, he lasted the longest.",
  ui_story_5068_50681201_27_dialog_content = "Why you...!",
  ui_story_5068_50681201_28_dialog_content = "At first I only wanted to take out my hatred of the Svanedona Family, but when I discovered your secret... I knew I had been chosen for something greater.",
  ui_story_5068_50681201_29_dialog_content = "You shouldn't be too upset with me either. After all, if I hadn't imprisoned them, they wouldn't have lived to see another year. Don't you agree?",
  ui_story_5068_50681201_30_dialog_content = "Besides, if anyone's to blame... It's them for not producing their venom until after they die. I can't make my black mist without it.",
  ui_story_5068_50681201_31_dialog_content = "But you're different, Rebecca. I'll be sure to cherish you for as long as possible—",
  ui_story_5068_50681201_32_dialog_content = "I won't let you do anything to her ever again!",
  ui_story_5068_50681201_33_dialog_content = "Oh? I think I recognize you. You're... the Caelestite, aren't you?",
  ui_story_5068_50681201_34_dialog_content = "Tch... If only we could've met under different circumstances.",
  ui_story_5068_50681201_35_dialog_content = "I've heard of your powers before... Maybe we'll have a chance to work together in the future?",
  ui_story_5068_50681201_36_dialog_content = "I'd never work with an inhumane jerk like you! Now where's Isa?!",
  ui_story_5068_50681201_37_dialog_content = "The feud between the Black Wolves and the Svanedona Family shouldn't concern a Caelestite, so won't you please stand down for now?",
  ui_story_5068_50681201_38_dialog_content = "In your dreams! I'm here to help my friend rescue her family!",
  ui_story_5068_50681201_39_dialog_content = "And here I was trying to be a good host. How ridiculous.",
  ui_story_5068_50681201_40_dialog_content = "Bring her out!",
  ui_story_5068_50681201_41_dialog_content = "...",
  ui_story_5068_50681201_42_dialog_content = "Isa!!",
  ui_story_5068_50681201_43_dialog_content = "Urgh... Rebecca? What are you doing here?!",
  ui_story_5068_50681201_44_dialog_content = "You shouldn't have come here! How could you fall for such an obvious trap?! Don't worry about me, just run before it's too late!",
  ui_story_5068_50681201_45_dialog_content = "Let go of my sister!",
  ui_story_5068_50681201_46_dialog_content = "Sure, I'd be more than happy to let her go. But—",
  ui_story_5068_50681201_47_dialog_content = "You have to stay in her place.",
  ui_story_5068_50681201_48_dialog_content = "What do you want?",
  ui_story_5068_50681201_49_dialog_content = "Was I not clear enough? Rebecca has to stay with the Black Wolves.",
  ui_story_5068_50681201_50_dialog_content = "I won't hurt a single hair on her; after all, she's the only one who can help me further my research on the black mist. I'm even willing to let bygones be bygones.",
  ui_story_5068_50681201_51_dialog_content = "I can also introduce you to <color=#FFB400>the woman</color> who recommended her to me in the first place.",
  ui_story_5068_50681201_52_dialog_content = "But if she steps out of line even once... Heheheh, you're welcome to try, Rebecca.",
  ui_story_5068_50681201_53_dialog_content = "Just know that cooperation isn't just in your best interest. It's also the only choice you have left.",
  ui_story_5068_50681201_54_dialog_content = "Are you kidding me? Talking about bygones and some woman... Rebecca's clearly the victim here!",
  ui_story_5068_50681201_55_dialog_content = "Oh? It's fine if the Caelestite doesn't know anything, but you Rebecca? Don't tell me you've been hiding your family's secrets just to take advantage of his trust?",
  ui_story_5068_50681201_56_dialog_content = "I have no idea what you're talking about.",
  ui_story_5068_50681201_57_dialog_content = "If that's the case, then your sister failed to tell you what happened between the Black Wolves and the Svanedona Family.",
  ui_story_5068_50681201_58_dialog_content = "Back then, all I wanted was to invite you to work with me, but the Svanedona Family looked down on us Black Wolves. Not only did they turn us away, they also hurt plenty of our members.",
  ui_story_5068_50681201_59_dialog_content = "Liar! The Black Wolves were the first to speak out of line! The fight only started because you thugs made the first move!",
  ui_story_5068_50681201_60_dialog_content = "Shut her up.",
  ui_story_5068_50681201_61_dialog_content = "Yes!",
  ui_story_5068_50681201_62_dialog_content = "Mmm, mmm, mmm—",
  ui_story_5068_50681201_63_dialog_content = "Invite me to work with you?",
  ui_story_5068_50681201_64_dialog_content = "Oh? I was right, it looks like you have no idea what actually happened.",
  ui_story_5068_50681201_65_dialog_content = "After all this time, not even your closest friend had the nerve to tell you?",
  ui_story_5068_50681201_66_dialog_content = "She knows all too well what happened back then. After all, she used to be a Black Wolf herself.",
  ui_story_5068_50681201_67_dialog_content = "...!!",
  ui_story_5068_50681201_68_dialog_content = "You don't mean... Eleanor?",
  ui_story_5068_50681301_1_dialog_content = "You don't mean... Eleanor?",
  ui_story_5068_50681301_2_dialog_content = "Heheheh. Surprised?",
  ui_story_5068_50681301_3_dialog_content = "Eleanor happens to be one of the oldest members in the Black Wolves' history.",
  ui_story_5068_50681301_4_dialog_content = "I sent her to infiltrate the Svanedona Family a long time ago... to gather intel every bit of intel on them.",
  ui_story_5068_50681301_5_dialog_content = "You could even say that the entire family's demise was all thanks to her.",
  ui_story_5068_50681301_6_dialog_content = "Eleanor... N-No... That's impossible!",
  ui_story_5068_50681301_7_dialog_content = "The day our family was attacked... Eleanor risked her life to save me!",
  ui_story_5068_50681301_8_dialog_content = "She's been at my side ever since, no matter what happened to us!",
  ui_story_5068_50681301_9_dialog_content = "Eleanor couldn't possibly be one of you!",
  ui_story_5068_50681301_10_dialog_content = "I'm just stating the facts, nothing more. Betraying others is a hard habit to break, Rebecca; you'd be smart to remember that.",
  ui_story_5068_50681301_11_dialog_content = "I'm surprised the hero of the Black Wolves isn't here with you today. Not that I really care, since you're the only one I'm interested in, Rebecca Svanedona.",
  ui_story_5068_50681301_12_dialog_content = "...",
  ui_story_5068_50681301_13_dialog_content = "(If Eleanor hasn't been captured, that means she's probably back at the clinic right now...)",
  ui_story_5068_50681301_14_dialog_content = "(That look in Rebecca's eyes... What could she be thinking?)",
  ui_story_5068_50681301_15_dialog_content = "But enough about all of that. Do you have an answer for me yet, Rebecca?",
  ui_story_5068_50681301_16_dialog_content = "Don't—!!!",
  ui_story_5068_50681301_17_dialog_content = "Mmm, mmm, mmm...",
  ui_story_5068_50681301_18_dialog_content = "Isa!!!",
  ui_story_5068_50681301_19_dialog_content = "That blade hanging over her head isn't just for looks, you know?",
  ui_story_5068_50681301_20_dialog_content = "At the end of the day, the only thing I'm after is that power of yours.",
  ui_story_5068_50681301_21_dialog_content = "If you had just joined us instead of hiding like a coward for the last year, the people in those jars wouldn't have died such shameful deaths.",
  ui_story_5068_50681301_22_dialog_content = "But now I'm giving you one last chance. If you don't want your sister to end up like the rest of them, admit that it was all your fault! Admit that you're the daughter of disaster!",
  ui_story_5068_50681301_23_dialog_content = "The daughter of disaster...",
  ui_story_5068_50681301_24_dialog_content = "... Is this really all my fault? My family's demise... The harmful venom that never stops flowing out of me...",
  ui_story_5068_50681301_25_dialog_content = "Ever since I was born, I could never reach out and touch nice things like a normal person...",
  ui_story_5068_50681301_26_dialog_content = "Don't listen to her, Rebecca! Just look at what she did to your entire family! You have no reason to surrender to her!",
  ui_story_5068_50681301_27_dialog_content = "Maybe so, but what other choice does she have?",
  ui_story_5068_50681301_28_dialog_content = "The poison in her body will be the end of her someday. Rather than let it go to waste, why not let me make something useful out of it?",
  ui_story_5068_50681301_29_dialog_content = "...",
  ui_story_5068_50681301_30_dialog_content = "(If this keeps up, Rebecca might actually make that choice...)",
  ui_story_5068_50681301_31_dialog_content = "(As a Caelestite, there's gotta be something I can do!)",
  ui_story_5068_50681301_32_option_content = "Force Boost!",
  ui_story_5068_50681301_33_dialog_content = "(Rebecca! Rebecca!)",
  ui_story_5068_50681301_34_dialog_content = "(... PlayerName? Is this... one of your powers too?)",
  ui_story_5068_50681301_35_dialog_content = "(Please just listen to me! There's no time to explain!)",
  ui_story_5068_50681301_36_dialog_content = "(I'm really sorry that your family had to meet its end like this... But trust me when I say none of it is your fault!)",
  ui_story_5068_50681301_37_dialog_content = "(How could you be the \"daughter of disaster\" when you've been hurting yourself so much just to save your patients? If anything, you're a guardian angel of Umbraton!)",
  ui_story_5068_50681301_38_dialog_content = "(If you don't believe me, try using your powers to rescue Isa right now!)",
  ui_story_5068_50681301_39_dialog_content = "(My powers... Can I really use them to save her?)",
  ui_story_5068_50681301_40_dialog_content = "(If I fight with my full power—)",
  ui_story_5068_50681301_41_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5068_50681301_42_dialog_content = "D... Director...",
  ui_story_5068_50681301_43_dialog_content = "You can do it, Rebecca!",
  ui_story_5068_50681301_44_dialog_content = "Isa!!!",
  ui_story_5068_50681301_45_dialog_content = "Mmm, mmm—!!",
  ui_story_5068_50681301_46_dialog_content = "<color=#e8d9bb>Click.</color>",
  ui_story_5068_50681301_47_dialog_content = "Stop resisting already. It's as dangerous as it is useless.",
  ui_story_5068_50681301_48_dialog_content = "Not even you can cure a bullet wound to the head, Rebecca.",
  ui_story_5068_50681301_49_dialog_content = "Mmm, mmm—!!",
  ui_story_5068_50681301_50_dialog_content = "...!!",
  ui_story_5068_50681301_51_dialog_content = "Isa—No!",
  ui_story_5068_50681301_52_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5068_50681301_53_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5068_50681301_54_dialog_content = "Urgh—! Who did that?!",
  ui_story_5068_50681301_55_dialog_content = "Now is the time, brothers!",
  ui_story_5068_50681301_56_dialog_content = "Yes!",
  ui_story_5068_50681301_57_dialog_content = "...",
  ui_story_5068_50681301_58_dialog_content = "?!",
  ui_story_5068_50681301_59_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  ui_story_5068_50681301_60_dialog_content = "It's you! How dare you fire a gun at me, Eleanor—!!!",
  ui_story_5068_50681301_61_dialog_content = "What? You heard it all? Or did I tell the story wrong?",
  ui_story_5068_50681301_62_dialog_content = "That's enough!!",
  ui_story_5068_50681301_63_dialog_content = "Sorry for showing up so late, Miss Rebecca. Are you okay?",
  ui_story_5068_50681301_64_dialog_content = "When I got back to the Cloudrover Guild, all I found was an empty room and a ransom note... So I came here as fast as I could.",
  ui_story_5068_50681301_65_dialog_content = "I'm fine, Eleanor, but please go check on Isa.",
  ui_story_5068_50681301_66_dialog_content = "Isa! Are you alright?!",
  ui_story_5068_50681301_67_dialog_content = "We were looking for you when Eleanor told us you got kidnapped, so we rushed over here with her!",
  ui_story_5068_50681301_68_dialog_content = "... I'm fine! In fact... I'm better than fine! It's time for me to repay the Black Wolves for their hospitality, so get ready for a fight!",
  ui_story_5068_50681301_69_dialog_content = "But you look really hurt, Isa! We should just get out of here while we have the chance!",
  ui_story_5068_50681301_70_dialog_content = "PlayerName is right... I'll clear a path out of here!",
  ui_story_5068_50681301_71_dialog_content = "I'm with you, Miss Rebecca!",
  ui_story_5068_50681301_72_dialog_content = "Alright, I'll support everyone in battle too!",
  ui_story_5068_50681302_1_dialog_content = "Forgive us, Director... We let them get away.",
  ui_story_5068_50681302_2_dialog_content = "...",
  ui_story_5068_50681302_3_dialog_content = "Director?",
  ui_story_5068_50681302_4_dialog_content = "It's fine. I don't mind playing with them a little longer, since they enjoy struggling so much.",
  ui_story_5068_50681302_X4_dialog_content = "I can count the number of places they can go on one hand. Let's prepare a nice welcoming gift for them before we go over there...",
  ui_story_5068_50681302_X5_dialog_content = "It's about time we played our trump card, now go get it ready!",
  ui_story_5068_50681302_5_dialog_content = "Today will be no different from the day the Svanedona Family died... It's all because you fools forced my hand!",
  ui_story_5068_50681302_6_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5068_50681302_7_dialog_content = "Phew—I... I don't think they're chasing us anymore...",
  ui_story_5068_50681302_X7_dialog_content = "I gotta say, you mercenaries really know how to hold your own! But shouldn't we be worried about the guys who covered our escape...?",
  ui_story_5068_50681302_X8_dialog_content = "We're all professionals, there's no need to worry about them. They'll regroup with us before too long.",
  ui_story_5068_50681302_8_dialog_content = "We've been running for so long... Is everyone still okay?",
  ui_story_5068_50681302_9_dialog_content = "... Don't stop just yet! This place isn't safe, and Arte won't let us go so easily!",
  ui_story_5068_50681302_10_dialog_content = "...",
  ui_story_5068_50681302_11_dialog_content = "How are you holding up, Rebecca? Even with my wound, you still look worse than I do!",
  ui_story_5068_50681302_12_dialog_content = "I'll... I'll be fine. Let's just get to a safe place first...",
  ui_story_5068_50681302_13_dialog_content = "Just hang on, Miss Rebecca!",
  ui_story_5068_50681302_14_dialog_content = "There are some abandoned warehouses up ahead. We can stop and catch our breath over there!",
  ui_story_5068_50681302_15_dialog_content = "My men and I will keep an eye out, so go ahead and get some rest. We won't stay here for much longer.",
  ui_story_5068_50681302_16_dialog_content = "Let me help you sit, Miss Rebecca...",
  ui_story_5068_50681302_17_dialog_content = "Hold it! Answer me one question right now: just who the hell are you—",
  ui_story_5068_50681302_18_dialog_content = "Isa!",
  ui_story_5068_50681302_19_dialog_content = "...",
  ui_story_5068_50681302_20_dialog_content = "Just stop, Isa... I don't want to know.",
  ui_story_5068_50681302_21_dialog_content = "Eleanor risked her life to save me from the Black Wolves twice now... That's all I need to know... Nothing more.",
  ui_story_5068_50681302_22_dialog_content = "But it's her fault too! She's the reason we lost our family!",
  ui_story_5068_50681302_23_dialog_content = "That's not the Eleanor I know...",
  ui_story_5068_50681302_24_dialog_content = "The Eleanor I know takes care of me when I lose consciousness... She bandages our patients' wounds and makes soup for the kids in our clinic. She—",
  ui_story_5068_50681302_25_dialog_content = "Miss Rebecca!",
  ui_story_5068_50681302_26_dialog_content = "I'm touched that you think so kindly of me... But the more you keep mentioning these things, the more guilt I feel.",
  ui_story_5068_50681302_27_dialog_content = "I... I have a confession to make—",
  ui_story_5068_50681302_28_dialog_content = "No... Eleanor, please...",
  ui_story_5068_50681302_29_dialog_content = "It's all true... Every word of it.",
  ui_story_5068_50681302_30_dialog_content = "You...?!",
  ui_story_5068_50681302_31_dialog_content = "It's true that I used to be a member of the Black Wolves, and that I was sent to infiltrate the Svanedona Family.",
  ui_story_5068_50681302_32_dialog_content = "The reason I got so close to you was to extract information from her.",
  ui_story_5068_50681302_33_dialog_content = "I'm so sorry, Miss Rebecca.",
  ui_story_5068_50681401_1_dialog_content = "I can't recall either of my parents' faces. For as long as I could remember, I was living day by day, stealing whatever I could to keep myself fed. Even the other people in the slums couldn't bear the sight of me.",
  ui_story_5068_50681401_2_dialog_content = "I was lying in a pile of garbage one day, starving to death... That's when the Black Wolves took me in.",
  ui_story_5068_50681401_3_dialog_content = "Back then, the Black Wolves were completely different from what they are today. They were like one big family, and I was far from the only helpless kid among them.",
  ui_story_5068_50681401_4_dialog_content = "Arte was the one who led our struggle for survival, and told us to always take care of each other.",
  ui_story_5068_50681401_5_dialog_content = "Slowly but surely, more and more people joined the Black Wolves. Arte's goals became even more ambitious too, which is why we started to fight with other gangs.",
  ui_story_5068_50681401_6_dialog_content = "I was furious when I heard that the Svanedona Family had hurt my brothers and sisters in the Black Wolves. I thought the Svanedonas were nothing more than crooks who bullied the weak... After all, who could forgive people for hurting my own family?",
  ui_story_5068_50681401_7_dialog_content = "Soon afterward, Arte gave me the order to infiltrate the Svanedona Family and get close to Miss Rebecca. I was supposed to wait for the perfect time to kidnap her...",
  ui_story_5068_50681401_8_dialog_content = "But after spending day after happy day with you, something strange started to come over me...",
  ui_story_5068_50681401_9_dialog_content = "You treated me just like family. Your trust and kindness also touched the hearts of the rest of your family.",
  ui_story_5068_50681401_10_dialog_content = "...",
  ui_story_5068_50681401_11_dialog_content = "For the Black Wolves, getting injured is shameful, but it was different with you and your family. Whenever I got hurt, you never responded with mockery but with love and kindness.",
  ui_story_5068_50681401_12_dialog_content = "To me, that's what being a family truly means.",
  ui_story_5068_50681401_13_dialog_content = "Before I knew what Arte's true goal was, I tried to convince Arte to approach you in a more peaceful way. Unfortunately, we all know how that ended.",
  ui_story_5068_50681401_14_dialog_content = "I was conflicted, and I didn't know what to do—I couldn't betray the Black Wolves, but I also couldn't bring myself to hurt Miss Rebecca in any way.",
  ui_story_5068_50681401_15_dialog_content = "In the end, I made a decision that I'll regret for the rest of my life—",
  ui_story_5068_50681401_16_dialog_content = "I ran away.",
  ui_story_5068_50681401_17_dialog_content = "And because I ran away, Arte and the Black Wolves had a chance to attack the Svanedona Family.",
  ui_story_5068_50681401_18_dialog_content = "I hoped against hope that Miss Rebecca was okay. When I finally made it back, I found her face-to-face with a bloodthirsty Arte.",
  ui_story_5068_50681401_19_dialog_content = "She was screaming madly at the top of her lungs, saying things like, \"How dare you look down on me! On the fate of the Black Wolves!!!\" She was a completely different person from the Arte I once knew.",
  ui_story_5068_50681401_20_dialog_content = "She was always so protective of her family in the past. I had no idea what happened to make her change like that; all I knew was that I needed to save Miss Rebecca and get her out of there right away.",
  ui_story_5068_50681401_21_dialog_content = "...",
  ui_story_5068_50681401_22_dialog_content = "You think saying any of this will make us forgive you? Rebecca and I lost our entire family, you murderer!",
  ui_story_5068_50681401_23_dialog_content = "...",
  ui_story_5068_50681401_24_dialog_content = "Rebecca, I know I don't deserve your forgiveness, much less all of the trust and kindness you've shown me in the last year.",
  ui_story_5068_50681401_25_dialog_content = "A person like me doesn't have the right to live...",
  ui_story_5068_50681401_26_dialog_content = "So please just kill me, Miss Rebecca!",
  ui_story_5068_50681401_27_dialog_content = "...",
  ui_story_5068_50681401_28_dialog_content = "How dare you! You know Rebecca would never do something like that! Even now, you're still just taking advantage of her kindness, you—",
  ui_story_5068_50681401_29_dialog_content = "Eleanor, did you ever consider what kind of life Rebecca would have if she killed you?",
  ui_story_5068_50681401_30_dialog_content = "But I don't deserve any better!",
  ui_story_5068_50681401_31_dialog_content = "If it would make her feel better, even just a little bit...",
  ui_story_5068_50681401_32_dialog_content = "<color=#e8d9bb>Bang, bang!</color>",
  ui_story_5068_50681401_33_dialog_content = "What's going on out there...?",
  ui_story_5068_50681401_34_dialog_content = "Someone's approaching! We need to get out of here!",
  ui_story_5068_50681401_35_dialog_content = "No... How did the Black Wolves catch up to us so quickly?!",
  ui_story_5068_50681401_36_dialog_content = "Let's go, Miss Rebecca!",
  ui_story_5068_50681401_37_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5068_50681401_38_dialog_content = "Over here!",
  ui_story_5068_50681401_39_dialog_content = "That was easier than I expected. Looks like our little game of cat and mouse is over now.",
  ui_story_5068_50681401_40_dialog_content = "Enough of all this pointless struggling. Come along quietly, and I might just leave some corpses to bury afterward!",
  ui_story_5068_50681401_41_dialog_content = "No one's coming along quietly with scum like you! Get her, men!",
  ui_story_5068_50681401_42_dialog_content = "Roger!",
  ui_story_5068_50681401_43_dialog_content = "Look out! She's carrying something dangerous in her hands!",
  ui_story_5068_50681402_1_dialog_content = "<color=#e8d9bb>Hiss—</color>",
  ui_story_5068_50681402_2_dialog_content = "Cough, cough...",
  ui_story_5068_50681402_3_dialog_content = "This black mist...",
  ui_story_5068_50681402_4_dialog_content = "What's happening? I thought Rebecca was immune to the black mist?!",
  ui_story_5068_50681402_5_dialog_content = "I really do pity you, Rebecca. Born into a family with such incredible innate abilities... I'm amazed that none of you ever thought to research the secrets behind your powers.",
  ui_story_5068_50681402_6_dialog_content = "But that's okay. I've already done much of that for you, and I'm proud to present you with the fruits of my research—",
  ui_story_5068_50681402_7_dialog_content = "A black mist capable of counteracting your venom.",
  ui_story_5068_50681402_8_dialog_content = "But... how...",
  ui_story_5068_50681402_9_dialog_content = "Heheh, don't you think there's something special about this mist? Something remarkably familiar, perhaps?",
  ui_story_5068_50681402_10_dialog_content = "What... What are you trying to say...?",
  ui_story_5068_50681402_11_dialog_content = "Doesn't it remind you of your parent's warm embrace?",
  ui_story_5068_50681402_12_dialog_content = "What the hell is this crazy woman talking about?!",
  ui_story_5068_50681402_13_dialog_content = "Unlike your stingy family members, I'm all too happy to share the formula of this black mist with you.",
  ui_story_5068_50681402_14_dialog_content = "This mist... was once your precious parent.",
  ui_story_5068_50681402_15_dialog_content = "—?!",
  ui_story_5068_50681402_16_dialog_content = "After an entire year of research, I finally uncovered the Svanedona Family's secret: the parents in your family have a neutralizing, even corroding effect on the abilities of their offspring.",
  ui_story_5068_50681402_17_dialog_content = "It's thanks to this, Rebecca, that I can keep you so well-behaved. I ought to thank your parent for saving me so much effort.",
  ui_story_5068_50681402_18_dialog_content = "H-How could you do something so heartless? Using her family against her...",
  ui_story_5068_50681402_19_dialog_content = "Arte! Have you... Have you lost your mind?! Don't you remember what you always told us?! \"The worst people in the world are those who shamelessly prey on the weak!\"",
  ui_story_5068_50681402_20_dialog_content = "Just look at you now! Even a year ago I still had some sympathy for you, since I thought you were only after revenge. But now I see that you're a totally different person!",
  ui_story_5068_50681402_21_dialog_content = "What could have twisted you like this? Was it the thrill of power and killing?",
  ui_story_5068_50681402_22_dialog_content = "Or maybe you've always been like this? Have you been using us from the very beginning...?",
  ui_story_5068_50681402_23_dialog_content = "Heheh... Hahahaha! What would you know?!",
  ui_story_5068_50681402_24_dialog_content = "I found you starving in the trash, a pitiful wretch that even dogs looked down on! Where would you be right now if it wasn't for me?!",
  ui_story_5068_50681402_25_dialog_content = "The Black Wolves would never have survived this long if I hadn't lied, cheated, and stolen every single step of the way!",
  ui_story_5068_50681402_26_dialog_content = "Is that why you turned our brothers and sisters in the Black Wolves into tools for your personal benefit?!",
  ui_story_5068_50681402_27_dialog_content = "If so, then betraying you was the smartest decision I've made in my life.",
  ui_story_5068_50681402_28_dialog_content = "Enough!",
  ui_story_5068_50681402_29_dialog_content = "<color=#e8d9bb>Click.</color>",
  ui_story_5068_50681402_30_dialog_content = "... Traitors have no right to criticize the Black Wolves.",
  ui_story_5068_50681402_31_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5068_50681402_32_dialog_content = "Heh. Looks like your shooting's gotten rusty, Director.",
  ui_story_5068_50681402_33_dialog_content = "Tsk.",
  ui_story_5068_50681402_34_dialog_content = "<color=#e8d9bb>Bang, bang, bang!</color>",
  ui_story_5068_50681402_35_dialog_content = "No... Stop it... Urgh...",
  ui_story_5068_50681402_36_dialog_content = "There's no use struggling until the bitter end, Rebecca.",
  ui_story_5068_50681402_37_dialog_content = "Dead or alive, I can still use you to continue my research, so don't say I never gave you a chance to survive! All of you are going to die here!",
  ui_story_5068_50681402_38_dialog_content = "... Look out, Miss Rebecca!",
  ui_story_5068_50681402_39_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5068_50681402_40_dialog_content = "<color=#e8d9bb>Spurt!</color>",
  ui_story_5068_50681402_41_dialog_content = "<size=50>Eleanor?!</size>",
  ui_story_5068_50681402_42_dialog_content = "No... Why are you guys just standing around?! The enemy's right in front of you, so open fire!",
  ui_story_5068_50681402_43_dialog_content = "Fire!",
  ui_story_5068_50681402_44_dialog_content = "Let's go get 'em!",
  ui_story_5068_50681402_45_dialog_content = "Yes, sir!!!",
  ui_story_5068_50681402_46_dialog_content = "Eleanor... Can you hear me...?",
  ui_story_5068_50681402_47_dialog_content = "Rebecca... I never thought I'd hear you... call my name again... I thought you would abandon me.",
  ui_story_5068_50681402_48_dialog_content = "But if I can die... in your arms... then I have no regrets...",
  ui_story_5068_50681402_49_dialog_content = "D-Don't say things like that! I can heal you, just give me some time...",
  ui_story_5068_50681402_50_dialog_content = "Don't... It's too late for me... Don't bother wasting your powers... on someone like me...",
  ui_story_5068_50681402_51_dialog_content = "Just get out of here... and find someplace... where they'll never find you...",
  ui_story_5068_50681402_52_dialog_content = "Don't forget, I'm a doctor... I could never abandon any of my patients... especially you.",
  ui_story_5068_50681402_53_dialog_content = "Argh! I still can't use my full power... But how else am I supposed to recover...?",
  ui_story_5068_50681402_54_dialog_content = "Wait... That's it! The jars and bottles at the clinic! I just need to go back and replenish my venom and serum, and then I can—",
  ui_story_5068_50681402_55_dialog_content = "The clinic... isn't safe...",
  ui_story_5068_50681402_56_dialog_content = "There's no need... to risk your life for me...",
  ui_story_5068_50681402_57_dialog_content = "Just... run...",
  ui_story_5068_50681402_58_dialog_content = "She's after you, Rebecca! I'll have my team cover Eleanor while you escape!",
  ui_story_5068_50681402_59_dialog_content = "PlayerName, take Rebecca and find a way out of here! I'm counting on you!",
  ui_story_5068_50681402_60_dialog_content = "Alright! Let's go, Rebecca!",
  ui_story_5068_50681402_61_dialog_content = "Running away, are we?",
  ui_story_5068_50681402_62_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5068_50681402_63_dialog_content = "I... I won't let you get in Rebecca's way! Your fight... is with me!",
  ui_story_5068_50681402_64_dialog_content = "Don't flatter yourself.",
  ui_story_5068_50681402_65_dialog_content = "<color=#e8d9bb>Bang, bang!!!</color>",
  ui_story_5068_50681402_66_dialog_content = "Urgh...",
  ui_story_5068_50681402_67_dialog_content = "—!!!",
  ui_story_5068_50681402_68_dialog_content = "R... Run...",
  ui_story_5068_50681402_69_dialog_content = "Eleanor...",
  ui_story_5068_50681402_70_dialog_content = "... Everyone retreats! Get out of here, Rebecca!",
  ui_story_5068_50681402_71_dialog_content = "Hraaagh—!!",
  ui_story_5068_50681402_72_dialog_content = "Cough...",
  ui_story_5068_50681402_73_dialog_content = "How dare you bite me!",
  ui_story_5068_50681402_74_dialog_content = "Watch it, the rest of you! This is how we handle traitors—",
  ui_story_5068_50681402_75_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang! Bang!</color>",
  ui_story_5068_50681402_76_dialog_content = "...",
  ui_story_5068_50681402_77_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5068_50681402_78_dialog_content = "Ah—! Papa? Papa!!!",
  ui_story_5068_50681402_79_dialog_content = "Run... Hurry...",
  ui_story_5068_50681402_80_dialog_content = "Rebecca... Run!",
  ui_story_5068_50681402_81_dialog_content = "<color=#e8d9bb>砰砰砰砰砰砰！！！</color>",
  ui_story_5068_50681402_82_dialog_content = "Rebecca!",
  ui_story_5068_50681402_83_dialog_content = "Don't look back, Rebecca! Do you hear me?!",
  ui_story_5068_50681402_84_dialog_content = "... Don't let Eleanor's sacrifice be in vain.",
  ui_story_5068_50681402_85_dialog_content = "Where's Eleanor, Isa? Didn't you promise to save her?",
  ui_story_5068_50681402_86_dialog_content = "She's... beyond saving, Rebecca...",
  ui_story_5068_50681402_87_dialog_content = "But how could that be? I haven't even started treating her yet...",
  ui_story_5068_50681402_88_dialog_content = "N-No... I won't abandon Eleanor like this...",
  ui_story_5068_50681402_89_dialog_content = "Rebecca... It's too late now.",
  ui_story_5068_50681402_90_dialog_content = "PlayerName... You think I failed her as a doctor too, don't you...?",
  ui_story_5068_50681402_91_dialog_content = "It's all my fault for not being able to use my powers. If it wasn't for me, Eleanor would still...",
  ui_story_5068_50681402_92_dialog_content = "All my hard work, all my research, it was all so that I could heal and protect others...",
  ui_story_5068_50681402_93_dialog_content = "So why... Why am I still so useless? Why does it have to be this way?",
  ui_story_5068_50681402_94_dialog_content = "Wait, that's right. I still have all those bottles of venom and serum. If I can use them to regain my powers, I can save Eleanor and everyone else...!",
  ui_story_5068_50681402_95_dialog_content = "Huh? Where do you think you're going, Rebecca?!",
  ui_story_5068_50681501_1_dialog_content = "Wait, Rebecca! Where are you going?!",
  ui_story_5068_50681501_2_dialog_content = "It took all we had just to escape, and the Black Wolves could show up at any second. We need to hurry back to the Cloudrover Guild!",
  ui_story_5068_50681501_3_dialog_content = "I have to... replenish my venom... and my serum...",
  ui_story_5068_50681501_4_dialog_content = "... Please don't scare me like this, Rebecca...",
  ui_story_5068_50681501_5_dialog_content = "I know you're in a lot of pain after losing Eleanor, but she did what she did to save you! So please, just look at me.",
  ui_story_5068_50681501_6_dialog_content = "I have to... replenish my venom...",
  ui_story_5068_50681501_7_dialog_content = "She keeps talking about replenishing her venom... I think she's trying to go back to the clinic.",
  ui_story_5068_50681501_8_dialog_content = "But will she... really be okay like this?",
  ui_story_5068_50681501_9_dialog_content = "...",
  ui_story_5068_50681501_10_dialog_content = "Rebecca!",
  ui_story_5068_50681501_11_dialog_content = "<color=#e8d9bb>Some distance away</color>",
  ui_story_5068_50681501_12_dialog_content = "Director... Are you sure you're okay?",
  ui_story_5068_50681501_13_dialog_content = "You think these wounds can stop me? Have you forgotten how we managed to survive all this time?",
  ui_story_5068_50681501_14_dialog_content = "Tell me, is it ready yet?",
  ui_story_5068_50681501_15_dialog_content = "Yes, Director.",
  ui_story_5068_50681501_16_dialog_content = "That's far enough. I'm done dealing with all of this pointless. I'll take what I want once she's been destroyed.",
  ui_story_5068_50681501_17_dialog_content = "I wonder... Will my fireworks make this garbage heap any more beautiful?",
  ui_story_5068_50681501_18_dialog_content = "<color=#e8d9bb>Kaboom!</color>",
  ui_story_5068_50681501_19_dialog_content = "Ahh—",
  ui_story_5068_50681501_20_dialog_content = "Rebecca! Isa!",
  ui_story_5068_50681501_21_dialog_content = "*coughing* ... Isa?!",
  ui_story_5068_50681501_22_dialog_content = "...",
  ui_story_5068_50681501_23_dialog_content = "Isa! Wake up...!",
  ui_story_5068_50681501_24_dialog_content = "My venom... will save everyone...",
  ui_story_5068_50681501_25_dialog_content = "Stop, Rebecca! The clinic's gonna explode! Don't go in there!!!",
  ui_story_5068_50681501_26_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5068_50681501_27_dialog_content = "It exploded... Heheh...",
  ui_story_5068_50681501_28_dialog_content = "Eleanor... In the end... I couldn't even save our clinic...",
  ui_story_5068_50681501_29_dialog_content = "...? M-My earrings! Where are the earrings Eleanor gave me?!",
  ui_story_5068_50681501_30_dialog_content = "...",
  ui_story_5068_50681501_31_dialog_content = "They're gone... it's all gone.",
  ui_story_5068_50681501_32_dialog_content = "Rebecca?!",
  ui_story_5068_50681501_33_dialog_content = "Why? Why does it have to be this way...?",
  ui_story_5068_50681501_34_dialog_content = "My family's gone, Eleanor's gone, our home is gone, and even the earrings she made for me are gone—I have nothing left.",
  ui_story_5068_50681501_35_dialog_content = "That's not true, Rebecca! What about Isa? You still have your sister!",
  ui_story_5068_50681501_36_dialog_content = "Ugh...",
  ui_story_5068_50681501_37_dialog_content = "Re... becca...",
  ui_story_5068_50681501_38_dialog_content = "... Thank goodness, she's still alive!",
  ui_story_5068_50681501_39_dialog_content = "It's too dangerous down there, Rebecca! Isa still needs you, so please come back!",
  ui_story_5068_50681501_40_dialog_content = "Isa... needs me...?",
  ui_story_5068_50681501_41_dialog_content = "M-My sister still needs me!",
  ui_story_5068_50681501_42_dialog_content = "(Are you sure? After all, who could possibly need someone who only brings pain and suffering wherever she goes?)",
  ui_story_5068_50681501_43_dialog_content = "It was me... I'm the one who did all of this...",
  ui_story_5068_50681501_44_dialog_content = "(Your so-called \"gift\" is the cause of all this suffering. Do you really think you deserve to keep living?)",
  ui_story_5068_50681501_45_dialog_content = "That's right... My power is what brought the Black Wolves to our family's doorstep. Because of me, they're all...",
  ui_story_5068_50681501_46_dialog_content = "My power is what created the black mist that made so many people in the slums sick...",
  ui_story_5068_50681501_47_dialog_content = "(What about Eleanor? Her death is also on your hands, and let's not forget about your sister, who already has one foot in the grave.)",
  ui_story_5068_50681501_48_dialog_content = "(You don't honestly think you can defeat the Black Wolves with a cursed power like yours, do you?)",
  ui_story_5068_50681501_49_dialog_content = "(And even if you do, who's to say someone else won't come looking for your power? You already lost Eleanor; who's going to pay the price next time? The people in the slums? Isa?)",
  ui_story_5068_50681501_50_dialog_content = "No! I won't let that happen... But how... How can I possibly protect them?",
  ui_story_5068_50681501_51_dialog_content = "(Heheh, the answer is simple. All you have to do...)",
  ui_story_5068_50681501_52_dialog_content = "(Is rid the world of your existence. Once you're gone, everything will be okay...)",
  ui_story_5068_50681501_53_dialog_content = "*coughing* Urgh... That hurts!",
  ui_story_5068_50681501_54_dialog_content = "You're awake, Isa!",
  ui_story_5068_50681501_55_dialog_content = "Idiot... Stop worrying about me... Rebecca's the one who needs... Argh—",
  ui_story_5068_50681501_56_dialog_content = "Stop moving! You're only gonna lose more blood if you do...",
  ui_story_5068_50681501_57_dialog_content = "You have to stop her... She looks like she's about to do something reckless...",
  ui_story_5068_50681501_58_dialog_content = "I-I'm her sister... I know what she's like, now go stop her...",
  ui_story_5068_50681501_59_dialog_content = "G-Got it!",
  ui_story_5068_50681501_60_dialog_content = "Rebecca!",
  ui_story_5068_50681501_61_dialog_content = "Rebecca? What are you...?",
  ui_story_5068_50681501_62_dialog_content = "... Don't come any closer!",
  ui_story_5068_50681501_63_dialog_content = "It's dangerous here.",
  ui_story_5068_50681501_64_dialog_content = "What are you planning to do?",
  ui_story_5068_50681501_65_dialog_content = "... The only thing I can do to stop hurting the people around me.",
  ui_story_5068_50681501_66_dialog_content = "Y-You're absorbing all this venom?!",
  ui_story_5068_50681501_67_dialog_content = "But your body... Can it really handle that much?!",
  ui_story_5068_50681501_68_dialog_content = "I'll be fine... Don't worry. It doesn't hurt at all...",
  ui_story_5068_50681501_69_dialog_content = "Um...!",
  ui_story_5068_50681501_70_dialog_content = "Stop it, Rebecca! You'll die if you don't!",
  ui_story_5068_50681501_71_dialog_content = "That's right... I'm doing this for everyone's sake...",
  ui_story_5068_50681501_72_dialog_content = "PlayerName... I should have died a long time ago. I don't know what made me think I could protect anyone...",
  ui_story_5068_50681501_73_dialog_content = "Don't say that! You promised me you wouldn't hurt yourself anymore!",
  ui_story_5068_50681501_74_dialog_content = "Heh, guess I'm going back on my word... This is Umbraton, after all. You can't believe everything you hear in this city.",
  ui_story_5068_50681501_75_dialog_content = "Umbraton has nothing to do with it, Rebecca! You're not that kind of person, so just stop it already! Think of Isa! You finally have a chance to be with your sister again!",
  ui_story_5068_50681501_76_dialog_content = "Urgh... Cough, cough...",
  ui_story_5068_50681501_77_dialog_content = "Isa... Sorry, but... Could you... keep an eye on her for me...?",
  ui_story_5068_50681501_78_dialog_content = "Please tell her that I'm sorry... And that this is the only way to put a stop to everything. I'm doing this for her too.",
  ui_story_5068_50681501_79_dialog_content = "(That's right. If you want this to end, keep absorbing this venom! Take it all in!!!)",
  ui_story_5068_50681501_80_dialog_content = "PlayerName... Please... Get my sister out of here.",
  ui_story_5068_50681501_81_dialog_content = "Rebecca...",
  ui_story_5068_50681501_82_dialog_content = "Go... Now—!!",
  ui_story_5068_50681501_83_dialog_content = "Ahhhh—!!!",
  ui_story_5068_50681501_84_dialog_content = "That should be enough, Rebecca...",
  ui_story_5068_50681501_85_dialog_content = "Leave the rest to me.",
  ui_story_5068_50681501_86_dialog_content = "Director! Rebecca's still alive, and it looks like she's absorbed a large amount of venom?",
  ui_story_5068_50681501_87_dialog_content = "But how?! Where could she have found so much venom...?",
  ui_story_5068_50681501_88_dialog_content = "It's from those broken jars... Her body's starting to transform from absorbing so much of it!",
  ui_story_5068_50681501_89_dialog_content = "... So, she's using the venom from those jars as an \"antidote\"?",
  ui_story_5068_50681501_90_dialog_content = "I don't think I'll be able to keep her under control once she finishes taking in all of that venom... Looks like—",
  ui_story_5068_50681501_91_dialog_content = "\"Looks like my only choice is to run away.\" Is that what you were going to say?",
  ui_story_5068_50681501_92_dialog_content = "Sheol...",
  ui_story_5068_50681501_93_dialog_content = "Assess the situation around the clinic and report back to me! Stay safe out there!",
  ui_story_5068_50681501_94_dialog_content = "Yes, Lady Sheol!",
  ui_story_5068_50681501_95_dialog_content = "So, you still remember me after all, Arte of the Black Wolves.",
  ui_story_5068_50681501_96_dialog_content = "... A run-down clinic like this shouldn't interest you or the Cloudrover Guild. Why have you brought your people here?",
  ui_story_5068_50681501_97_dialog_content = "\"Shouldn't interest us,\" you say? Our rambunctious little Isa is lying wounded on the ground, and PlayerName appears to be in mortal danger as well.",
  ui_story_5068_50681501_98_dialog_content = "Tell me, how should I handle this in accordance with our rules?",
  ui_story_5068_50681501_99_dialog_content = "According to the rules, the Cloudrover Guild has no authority in these slums.",
  ui_story_5068_50681501_100_dialog_content = "Sorry to disappoint you, but from this day forward, the Cloudrover Guild is in charge of this clinic.",
  ui_story_5068_50681501_101_dialog_content = "Now how are you going to repay us for what you've done to one of our doctors?",
  ui_story_5068_50681501_102_dialog_content = "...",
  ui_story_5068_50681501_103_dialog_content = "Lady Sheol! Isa and PlayerName are safe for now, but Rebecca's situation doesn't look too good! The rest of our people have already retreated!",
  ui_story_5068_50681501_104_dialog_content = "Don't tell me...",
  ui_story_5068_50681501_105_dialog_content = "Lady Sheol! You're finally here!",
  ui_story_5068_50681501_106_dialog_content = "L-Lady Sheol! It's Rebecca... You have to save her—",
  ui_story_5068_50681501_107_dialog_content = "Die—!!!",
  ui_story_5068_50681501_108_dialog_content = "... Poor girl. Just look at what they've done to her.",
  ui_story_5068_50681501_109_dialog_content = "Director! Should we... retreat for now?",
  ui_story_5068_50681501_110_dialog_content = "No! Use the black mist bombs!",
  ui_story_5068_50681501_111_dialog_content = "<color=#e8d9bb>Hiss—</color>",
  ui_story_5068_50681501_112_dialog_content = "It's not working?! But how—",
  ui_story_5068_50681501_113_dialog_content = "ARTE!!!",
  ui_story_5068_50681501_114_dialog_content = "I have a new job for you, PlayerName! Navigate our forces into battle!",
  ui_story_5068_50681501_115_dialog_content = "Rebecca needs our help right now!",
  ui_story_5068_50681501_116_dialog_content = "... G-Got it!",
  ui_story_5068_50681502_1_dialog_content = "Throw more bombs, you fools! Dump everything we have on her!",
  ui_story_5068_50681502_2_dialog_content = "But Director! If we use that many all at once, our protective equipment won't save us! Besides, everyone is already...",
  ui_story_5068_50681502_3_dialog_content = "Don't question me! We can't let that insane woman catch up to us!",
  ui_story_5068_50681502_4_dialog_content = "*coughing* I-It's too late, we already breathed it in... Urgh...",
  ui_story_5068_50681502_5_dialog_content = "...",
  ui_story_5068_50681502_6_dialog_content = "You there! Take some of our fighters and don't let Arte get away. The rest of you help clean up this mess.",
  ui_story_5068_50681502_7_dialog_content = "Understood!",
  ui_story_5068_50681502_8_dialog_content = "Re... Rebecca...",
  ui_story_5068_50681502_9_dialog_content = "It's me... Isa... Please wake up...",
  ui_story_5068_50681502_10_dialog_content = "...",
  ui_story_5068_50681502_11_dialog_content = "Urgh... Where... am I...?",
  ui_story_5068_50681502_12_dialog_content = "Rebecca! You're finally awake!",
  ui_story_5068_50681502_13_dialog_content = "Thank goodness—I thought I'd lost you again, Rebecca!",
  ui_story_5068_50681502_14_dialog_content = "—!!",
  ui_story_5068_50681502_15_dialog_content = "Wait, Rebecca! Wh-Where are you going?!",
  ui_story_5068_50681502_16_dialog_content = "D-Don't come near me!",
  ui_story_5068_50681502_17_dialog_content = "I think I turned into something else just now... This mist, and all of these injured people... Did I do this?",
  ui_story_5068_50681502_18_dialog_content = "All I wanted was to end it all, but instead I ended up hurting everyone again... I really am hopeless, aren't I? I don't want to make any more trouble for everyone, so just leave me alone—",
  ui_story_5068_50681502_19_dialog_content = "Don't be stupid, Rebecca!",
  ui_story_5068_50681502_20_dialog_content = "Isa?!",
  ui_story_5068_50681502_21_dialog_content = "No! Let go of me! My body—it's covered in venom!",
  ui_story_5068_50681502_22_dialog_content = "I won't let go! Not even if I die!",
  ui_story_5068_50681502_23_dialog_content = "You don't want to make any more trouble for everyone? When did I become everyone?! I'm your sister! You can make all the trouble you want for me, and I still wouldn't mind!",
  ui_story_5068_50681502_24_dialog_content = "Telling me to leave you alone after searching for you for so long... That's one thing I refuse to do!",
  ui_story_5068_50681502_25_dialog_content = "You wanna know something? I wrote a list of all the things I wanted to do with you the day we met again! And let me tell you, it's a long list!",
  ui_story_5068_50681502_26_dialog_content = "I wanna keep buying you lots of stuff just like before, and dressing you up in pretty clothes! I—",
  ui_story_5068_50681502_27_dialog_content = "I won't lose you ever again! You're not allowed to leave me either!",
  ui_story_5068_50681502_28_dialog_content = "That's an order from your big sister, so you have to listen! You hear me, Rebecca?!",
  ui_story_5068_50681502_29_dialog_content = "I... I want that too, Isa. I want to live the kind of life you just described, but it's too late now. I've absorbed too much venom, and soon I'll be...",
  ui_story_5068_50681502_30_dialog_content = "I just want to find a quiet, empty place where I can die alone.",
  ui_story_5068_50681502_31_dialog_content = "Even so... I'm staying with you no matter what!",
  ui_story_5068_50681502_32_dialog_content = "You want a nice, quiet place? Then I'll help you look for one! After that...",
  ui_story_5068_50681502_33_dialog_content = "After that, I'll make you a crown of flowers, just like when we were kids... I'll make you dozens, no, hundreds of them! So please, Rebecca—",
  ui_story_5068_50681502_34_dialog_content = "You need to let go of her first, Isa. Otherwise, you'll...",
  ui_story_5068_50681502_35_dialog_content = "No! I already said I won't let go, even if it kills me!",
  ui_story_5068_50681502_36_dialog_content = "Wait!",
  ui_story_5068_50681502_37_dialog_content = "... Rebecca's venom is supposed to corrode flesh. During our battle, a lot of us got burned by her venom.",
  ui_story_5068_50681502_38_dialog_content = "So how are you able to safely hold her when she's completely covered in venom?!",
  ui_story_5068_50681502_39_dialog_content = "... What are you saying?",
  ui_story_5068_50681502_40_dialog_content = "Wait, you're right! Rebecca's skin feels perfectly fine, just like usual!",
  ui_story_5068_50681502_41_dialog_content = "It's possible that you really did inherit one of the Svanedona Family's abilities, Isa... A cure for Rebecca's venom, one that can neutralize its effects!",
  ui_story_5068_50681502_42_dialog_content = "—!!",
  ui_story_5068_50681502_43_dialog_content = "There's no time to waste! Try doing something!",
  ui_story_5068_50681502_44_dialog_content = "Alright!",
  ui_story_5068_50681502_45_dialog_content = "...",
  ui_story_5068_50681502_46_dialog_content = "Well?",
  ui_story_5068_50681502_47_dialog_content = "I thought it was just because Isa was holding me... But the burn from my venom really feels a little less intense...",
  ui_story_5068_50681502_48_dialog_content = "Does that mean... it worked?",
  ui_story_5068_50681502_49_dialog_content = "Yes!",
  ui_story_5068_50681502_50_dialog_content = "Oh, thank goodness! I never would've guessed...",
  ui_story_5068_50681502_51_dialog_content = "You spent all that time treating everyone, but now it's my turn to treat you! I don't care how long it takes, I won't stop until you're all better!",
  ui_story_5068_50681502_52_dialog_content = "Isa...",
  ui_story_5068_50681502_53_dialog_content = "Oh wait, that reminds me.",
  ui_story_5068_50681502_54_dialog_content = "I found these earlier.",
  ui_story_5068_50681502_55_dialog_content = "These are... The earrings Eleanor gave me.",
  ui_story_5068_50681502_56_dialog_content = "... Want me to help you put them on?",
  ui_story_5068_50681502_57_dialog_content = "... Yes, please.",
  ui_story_5068_50681502_58_dialog_content = "Hmm... Now that I think about it, these earrings look really pretty on you.",
  ui_story_5068_50681502_59_dialog_content = "...",
  ui_story_5068_50681502_60_dialog_content = "Eleanor... Thanks for taking such good care of my sister. From now on, I promise to do the same.",
  ui_story_5068_50681601_1_dialog_content = "<color=#e8d9bb>A few days later</color>",
  ui_story_5068_50681601_2_dialog_content = "Here's your reward as promised. Feel free to make sure it's all there.",
  ui_story_5068_50681601_3_dialog_content = "... That job was way too dangerous, you know. And for some reason, I wasn't able to reach you even during the worst of it...",
  ui_story_5068_50681601_4_dialog_content = "The business world can be ruthless, but somehow you always manage to make things right, don't you?",
  ui_story_5068_50681601_5_dialog_content = "That's why, as the humble leader of the Cloudrover Guild, all I can do is ask for your patience and understanding.",
  ui_story_5068_50681601_6_dialog_content = "Sure, but... I just thought my compensation would be a little bigger after what I went through.",
  ui_story_5068_50681601_7_dialog_content = "Heheh, you drive an even harder bargain than Vice when you take charge. I'll have to be more careful around you from now on.",
  ui_story_5068_50681601_8_dialog_content = "Pardon me, Lady Sheol!",
  ui_story_5068_50681601_9_dialog_content = "Oh, hey, PlayerName! I didn't know you were here?",
  ui_story_5068_50681601_10_dialog_content = "Isa? And Rebecca too?",
  ui_story_5068_50681601_11_dialog_content = "Are you feeling any better yet?",
  ui_story_5068_50681601_12_dialog_content = "Yes. Thanks to Isa, I feel much better now.",
  ui_story_5068_50681601_13_dialog_content = "But you still have a long way to go before you're fully healed... Argh, if only I was a little stronger!",
  ui_story_5068_50681601_14_dialog_content = "Don't say that, Isa! I'm grateful just being together with you again.",
  ui_story_5068_50681601_15_dialog_content = "I'm grateful to see that our \"nameless doctor\" is slowly recovering too.",
  ui_story_5068_50681601_16_dialog_content = "Please don't joke like that, Ms. Sheol.",
  ui_story_5068_50681601_17_dialog_content = "Sorry, I couldn't help myself after seeing the two of you together like this... But now that everyone involved is here, I'd like to report my findings to you.",
  ui_story_5068_50681601_18_dialog_content = "After all, you have the right to know what became of the Black Wolves after the incident.",
  ui_story_5068_50681601_19_dialog_content = "But if you'd rather not hear about it...",
  ui_story_5068_50681601_20_dialog_content = "It's fine, Ms. Sheol. Please tell us.",
  ui_story_5068_50681601_21_dialog_content = "Sure. I'll try to make it brief.",
  ui_story_5068_50681601_22_dialog_content = "We've already collected enough evidence to implicate the Black Wolves in their wicked scheme to produce the black mist. As for Arte...",
  ui_story_5068_50681601_23_dialog_content = "She was also exposed to the black mist that night. Wherever she's hiding, I doubt she'll cause us any more trouble from now on.",
  ui_story_5068_50681601_24_dialog_content = "So, she got what she deserved! Good, now I can breathe a little easier.",
  ui_story_5068_50681601_25_dialog_content = "...",
  ui_story_5068_50681601_26_dialog_content = "Regarding your clinic, I'd be more than willing to help with its reconstruction.",
  ui_story_5068_50681601_27_dialog_content = "Thanks, but no thanks, Lady Sheol. You've already done more than enough for us.",
  ui_story_5068_50681601_28_dialog_content = "Heheh, I expected Rebecca to turn me down, not you.",
  ui_story_5068_50681601_29_dialog_content = "The truth is we came to say our farewells today, Ms. Sheol.",
  ui_story_5068_50681601_30_dialog_content = "I see... Are you sure you don't want to stay here? I'm not trying to force you to work for me or anything; I'd just be happier if the two of you stayed with the Cloudrover Guild.",
  ui_story_5068_50681601_31_dialog_content = "You say that, but you knew exactly what was on our minds the moment we walked in, didn't you, Lady Sheol?",
  ui_story_5068_50681601_32_dialog_content = "I saw it in your eyes, to be precise... So not only am I losing Rebecca, but also one of my most useful assistants. Oh, what a shame.",
  ui_story_5068_50681601_33_dialog_content = "I was even going to ask PlayerName to help me convince you to stay, but the poor boy hasn't said a word since you came in. I must say, I'm disappointed in him.",
  ui_story_5068_50681601_34_dialog_content = "Huh? I-I'm...",
  ui_story_5068_50681601_35_dialog_content = "Thank you for your generous offer, Ms. Sheol. But our minds are made up.",
  ui_story_5068_50681601_36_dialog_content = "And... Thank you for all your help as well, PlayerName. If you hadn't trusted me and stayed with me from the very beginning, I wouldn't be...",
  ui_story_5068_50681601_37_dialog_content = "Don't mention it! Though if you think about it, I really didn't do much...",
  ui_story_5068_50681601_38_dialog_content = "So where are you two gonna go next? Have you figured it out yet?",
  ui_story_5068_50681601_39_dialog_content = "In Umbraton, it's always best not to ask too many questions.",
  ui_story_5068_50681601_40_dialog_content = "Looks like the girls have a secret to keep.",
  ui_story_5068_50681601_41_dialog_content = "I-Is that so...? Then I won't pry anymore. But if you ever have the time, you should come visit Eraveil someday. The good weather and peaceful scenery should help with Rebecca's recovery.",
  ui_story_5068_50681601_42_dialog_content = "Thank you for the invitation, PlayerName. I have a feeling... We'll see each other again soon enough.",
  ui_story_5068_50681601_43_dialog_content = "Phew...",
  ui_story_5068_50681601_44_dialog_content = "Even though we took on yet another loss... The Shadowlord should be fully satisfied with the Cloudrover Guild's work.",
  ui_story_5068_50681601_45_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  ui_story_5068_50681601_46_dialog_content = "Are you done cleaning yet, Isa? And have you seen my earrings anywhere?",
  ui_story_5068_50681601_47_dialog_content = "Huh...? What are you looking at?",
  ui_story_5068_50681601_48_dialog_content = "Heeheehee...",
  ui_story_5068_50681601_49_dialog_content = "Is that... a photo book? Why does it only have pictures of me? And when did you take all of these?",
  ui_story_5068_50681601_50_dialog_content = "Huh? R-Rebecca?! Don't you ever knock before coming in?!",
  ui_story_5068_50681601_51_dialog_content = "But I did knock!",
  ui_story_5068_50681601_52_dialog_content = "Th-Then you should've waited for me to answer!",
  ui_story_5068_50681601_53_dialog_content = "Fine, I get it.",
  ui_story_5068_50681601_54_dialog_content = "Knock, knock, knock. Hello Isa, can I come in?",
  ui_story_5068_50681601_55_dialog_content = "Okay, now you're just teasing me! But let's see how you like this!",
  ui_story_5068_50681601_56_dialog_content = "Hahahaha—Stop, that tickles! I'm sorry, Isa! Just stop it, please!",
  ui_story_5068_50681601_57_dialog_content = "You're not getting off the hook that easily! Time for my ultimate attack!",
  ui_story_5068_50681601_58_dialog_content = "... So what's with all those pictures?",
  ui_story_5068_50681601_59_dialog_content = "You really don't know when to quit, do you? I just wanted to document your recovery, so I decided to take a few pictures!",
  ui_story_5068_50681601_60_dialog_content = "I see. Thank you for doing that for me, Isa...",
  ui_story_5068_50681601_61_dialog_content = "Heeheehee! I-It's nothing, really! So did you actually need something?",
  ui_story_5068_50681601_62_dialog_content = "I still can't find my earrings...",
  ui_story_5068_50681601_63_dialog_content = "Don't worry, they're right over here! See, I took good care of them! Want some help putting them on?",
  ui_story_5068_50681601_64_dialog_content = "Isa... Did I really do anything to deserve Eleanor sacrificing her life for me?",
  ui_story_5068_50681601_65_dialog_content = "Beats me. But since she was willing to go that far, you must've done something.",
  ui_story_5068_50681601_66_dialog_content = "At least that's what I think.",
  ui_story_5068_50681601_67_dialog_content = "...",
  ui_story_5068_50681601_68_dialog_content = "Oh, right, I almost forgot! Have you come up with a name for the new clinic yet?",
  ui_story_5068_50681601_69_dialog_content = "Not yet... But honestly, why don't we just call it \"The Nameless Clinic\"?",
  ui_story_5068_50681601_70_dialog_content = "Hoot— Hoot—",
  ui_story_5068_50681601_71_dialog_content = "My lady... I-I can't hold on much longer... But I know you can save me...",
  ui_story_5068_50681601_72_dialog_content = "... Save you? I can't think of a reason for doing that.",
  ui_story_5068_50681601_73_dialog_content = "I-I can still be of use to you... The Black Wolves, and the black mist...",
  ui_story_5068_50681601_74_dialog_content = "Yes, you have a point.",
  ui_story_5068_50681601_75_dialog_content = "Urgh—Th-Then—",
  ui_story_5068_50681601_76_dialog_content = "Your mistake last time was picking a fight with someone far outside of your league.",
  ui_story_5068_50681601_77_dialog_content = "Y... You mean Sheol... And the Cloudrover Guild?",
  ui_story_5068_50681601_78_dialog_content = "You were a faithful lapdog, Arte. But it seems you weren't content with just being a lapdog.",
  ui_story_5068_50681601_79_dialog_content = "O-Of course I was, my lady! I'll do whatever you ask! Just please save me—",
  ui_story_5068_50681601_80_dialog_content = "Enjoy these final, painful moments of your miserable life. We won't be meeting ever again.",
  ui_story_5068_50681601_81_dialog_content = "Please, my lady! Don't leave me like this! *cough, cough* Please... Save me—",
  ui_story_5068_50681601_82_dialog_content = "How unsightly.",
  ui_story_5068_50681601_83_dialog_content = "Still, it wasn't all for nothing...",
  ui_story_5068_50681601_84_dialog_content = "Wouldn't you agree, Rebecca?"
}
return config
